/* Tech 3D · Nivell 1 · unitat 8 «El meu disseny» (projecte final) · guia del professor (m8-1 … m8-4)
   Material propi de Numi. Classe de 60 minuts; mateix esquema que TGUIDE['r1-1']. Les diapositives «media» mostren el
   model en 3D (TMEDIA.model): a la pissarra digital es pot girar amb el dit o amb el ratolí. El disseny de cada alumne/a
   passa d'una sessió a l'altra: el pas de crear de cada sessió comença amb l'última versió desada a «Projectes». */
Object.assign(TGUIDE, (() => {
  const P = (id, t, s, p, c, o = {}) => ({ id, t, s, p, r: o.r || [0, 0, 0], c, ...o });
  const B = (id, t, s, x, y, z0, c, o = {}) => P(id, t, s, [x, y, z0 + (o.h ?? s[2]) / 2], c, o);
  const H = (id, t, s, p, o = {}) => P(id, t, s, p, '#9AA3B5', { hole: true, ...o });
  const HB = (id, t, s, x, y, z0, o = {}) => H(id, t, s, [x, y, z0 + s[2] / 2], o);
  const OR = '#FF8A3D', GR = '#F7C531';
  const COS = B('cos', 'cyl', [60, 60, 56], 0, 0, 0, OR), BUIT = HB('buit', 'cyl', [54, 54, 56], 0, 0, 3);
  const DR = [-12, 0, 12].map((x, i) => HB('d' + (i + 1), 'cyl', [6, 6, 6], x, 0, -1));
  const NR = B('n1', 'wedge', [10, 16, 12], 33, 0, 38, OR, { r: [180, 0, 0] }), NL = B('n2', 'wedge', [10, 16, 12], -33, 0, 38, OR, { r: [0, 180, 0] });
  const V1 = [COS, BUIT], V2 = [...V1, ...DR, NR, NL];
  const JANA = { parts: [...V2, B('etiqueta', 'box', [24, 4, 16], 0, -30, 18, GR), P('cor', 'heart', [14, 14, 4], [0, -33, 26], '#E8453C', { r: [90, 0, 0] })] };
  const IDEA0 = { parts: [...V1, B('pal', 'cyl', [4, 4, 86], 16, 0, 3, '#A0683A'), B('retol', 'box', [30, 3, 18], 16, 0, 70, '#F3F3EE')] };
  const BIEL = { parts: [B('got', 'cyl', [40, 40, 60], 0, 0, 0, '#5BC0EB'), HB('forat', 'cyl', [38, 38, 60], 0, 0, 3), H('tall', 'box', [60, 30, 70], [0, -15, 30])] };
  const NINOT = { parts: [B('peu', 'cyl', [30, 30, 4], 0, 0, 0, '#F3F3EE'), B('cos', 'sph', [34, 34, 34], 0, 0, 0, '#F3F3EE'), B('cap', 'sph', [24, 24, 24], 0, 0, 30, '#F3F3EE'), P('nas', 'cone', [5, 5, 8], [0, -14, 42], OR, { r: [90, 0, 0] }), B('barret', 'cyl', [16, 16, 12], 0, 0, 57, '#1B2B6B')] };
  const PRIMS = { parts: [B('g1', 'cyl', [30, 30, 36], -24, 0, 0, '#5BC0EB'), HB('f1', 'cyl', [28, 28, 36], -24, 0, 2), B('g2', 'cyl', [30, 30, 36], 24, 0, 0, '#2FB36D'), HB('f2', 'cyl', [26, 26, 36], 24, 0, 2), H('tall', 'box', [100, 20, 50], [0, -10, 20])] };
  const PT = { parts: [B('bloc', 'box', [60, 24, 16], 0, 0, 0, '#14A3B8'), HB('ranura', 'box', [56, 3, 12], 0, 0, 5)] };
  const TROF = { parts: [B('base', 'cyl', [44, 44, 6], 0, 0, 0, '#1B2B6B'), B('columna', 'cyl', [12, 12, 30], 0, 0, 6, GR), B('bola', 'sph', [26, 26, 26], 0, 0, 32, GR)] };
  return {
  /* ---------- Sessió 1 · La idea ---------- */
  'm8-1': {
    obj: ["L'alumne/a escriu l'encàrrec del seu projecte final: per a qui és, quin problema resol i on es farà servir.|El alumno/a escribe el encargo de su proyecto final: para quién es, qué problema resuelve y dónde se usará.",
      "L'alumne/a formula requisits que es poden comprovar (mides, ús, material i impressió) i els relaciona amb les comprovacions del taller.|El alumno/a formula requisitos que se pueden comprobar (medidas, uso, material e impresión) y los relaciona con las comprobaciones del taller.",
      "L'alumne/a dibuixa un esbós de davant i de dalt amb les cotes en mil·límetres.|El alumno/a dibuja un boceto de delante y de arriba con las cotas en milímetros.",
      "L'alumne/a passa les cotes de l'esbós al taller i desa la primera versió del seu disseny.|El alumno/a pasa las cotas del boceto al taller y guarda la primera versión de su diseño."],
    comp: ["Tecnologia i digitalització: el procés tecnològic (necessitat, especificacions, disseny)|Tecnología y digitalización: el proceso tecnológico (necesidad, especificaciones, diseño)",
      "Matemàtiques, sentit espacial: representar un objecte amb vistes (alçat i planta)|Matemáticas, sentido espacial: representar un objeto con vistas (alzado y planta)",
      "Matemàtiques, sentit de la mesura: mides màximes i cotes en mil·límetres|Matemáticas, sentido de la medida: medidas máximas y cotas en milímetros",
      "Competència personal i d'aprendre a aprendre: planificar un projecte propi en quatre sessions|Competencia personal y de aprender a aprender: planificar un proyecto propio en cuatro sesiones"],
    vocab: [['Encàrrec (brief)|Encargo (brief)', "Poques frases que diuen per a qui és un disseny, quin problema resol i on es farà servir.|Pocas frases que dicen para quién es un diseño, qué problema resuelve y dónde se usará."],
      ['Requisit|Requisito', "Una cosa que el disseny ha de complir i que es pot comprovar, sovint amb un número.|Algo que el diseño tiene que cumplir y que se puede comprobar, a menudo con un número."],
      ['Esbós|Boceto', "Dibuix ràpid a llapis, de davant i de dalt, per pensar com serà l'objecte.|Dibujo rápido a lápiz, de delante y de arriba, para pensar cómo será el objeto."],
      ['Cota|Cota', "Una mida escrita a l'esbós, amb una fletxa i un número en mil·límetres.|Una medida escrita en el boceto, con una flecha y un número en milímetros."],
      ['Mida màxima|Medida máxima', "La mida que el disseny no pot passar (per exemple, perquè càpiga en un lloc).|La medida que el diseño no puede pasar (por ejemplo, para que quepa en un sitio)."],
      ['Prototip|Prototipo', "La primera versió d'un objecte, feta per provar-la i millorar-la.|La primera versión de un objeto, hecha para probarla y mejorarla."]],
    mat: { aula: ["Un ordinador per alumne/a amb Numi Tech obert a la sessió «La idea»|Un ordenador por alumno/a con Numi Tech abierto en la sesión «La idea»", 'Projector i la presentació de la sessió|Proyector y la presentación de la sesión',
      "La fitxa del projecte, un regle i un llapis per alumne/a|La ficha del proyecto, una regla y un lápiz por alumno/a"],
      imprimir: ['Fitxa del meu projecte|Ficha de mi proyecto'],
      prep: ["Imprimir la fitxa del projecte: l'alumnat la farà servir les quatre sessions, així que convé guardar-la en una carpeta.|Imprimir la ficha del proyecto: el alumnado la usará las cuatro sesiones, así que conviene guardarla en una carpeta.",
        "Tenir a mà les fitxes d'especificacions de la unitat 7: algunes idees poden continuar l'invent per a l'escola.|Tener a mano las fichas de especificaciones de la unidad 7: algunas ideas pueden continuar el invento para la escuela.",
        "Si podeu, portar dos o tres objectes reals senzills per mesurar (un got, un estoig, un test petit).|Si podéis, traer dos o tres objetos reales sencillos para medir (un vaso, un estuche, una maceta pequeña)."] },
    plan: [
      { min: 5, t: "La Fira d'Invents|La Feria de Inventos", fase: 'inici', fa: "Presenta el projecte final: cada alumne/a portarà un disseny propi a la Fira d'Invents. Explica les quatre sessions (idea, modelar, revisar i presentar) i pregunta quins objectes útils inventarien per a algú que coneixen.|Presenta el proyecto final: cada alumno/a llevará un diseño propio a la Feria de Inventos. Explica las cuatro sesiones (idea, modelar, revisar y presentar) y pregunta qué objetos útiles inventarían para alguien que conocen.",
        diu: ['Per a qui us agradaria fer un invent? Què li costa o li fa nosa?|¿Para quién os gustaría hacer un invento? ¿Qué le cuesta o le molesta?', "Què hauria de tenir un invent perquè la Nuvi el pugui imprimir?|¿Qué tendría que tener un invento para que Nuvi lo pueda imprimir?"], slides: ['s1', 's2'], app: 'Encara no: pantalles abaixades.|Todavía no: pantallas bajadas.', org: 'Tot el grup|Todo el grupo' },
      { min: 10, t: "L'encàrrec, els requisits i l'esbós|El encargo, los requisitos y el boceto", fase: 'teoria', fa: "Explica el camí del projecte i les tres peces de la idea amb l'exemple de la Jana: l'encàrrec (per a qui, quin problema, on), els requisits amb números i l'esbós de dues vistes amb cotes. Gira el test en 3D per relacionar cada requisit amb una part del model.|Explica el camino del proyecto y las tres piezas de la idea con el ejemplo de Jana: el encargo (para quién, qué problema, dónde), los requisitos con números y el boceto de dos vistas con cotas. Gira la maceta en 3D para relacionar cada requisito con una parte del modelo.",
        diu: ["«Ha de ser bonic»: es pot comprovar? Com el diríeu perquè es pogués comprovar?|«Tiene que ser bonito»: ¿se puede comprobar? ¿Cómo lo diríais para que se pudiera comprobar?", "Quina vista ens diu l'alçada? I quina, els forats del fons?|¿Qué vista nos dice la altura? ¿Y cuál, los agujeros del fondo?"], slides: ['s3', 's4', 's5', 's6', 's7'], app: "Encara no: tota l'atenció a la projecció.|Todavía no: toda la atención en la proyección.", org: 'Tot el grup|Todo el grupo' },
      { min: 14, t: 'La fitxa del meu projecte|La ficha de mi proyecto', fase: 'desconnectat', fa: "Cada alumne/a omple la fitxa: tres idees, l'encàrrec, tres requisits amb números i l'esbós de davant i de dalt amb cotes. Passa per les taules per ajudar a triar una idea que es pugui modelar en dues sessions i que càpiga a la placa.|Cada alumno/a rellena la ficha: tres ideas, el encargo, tres requisitos con números y el boceto de delante y de arriba con cotas. Pasa por las mesas para ayudar a elegir una idea que se pueda modelar en dos sesiones y que quepa en la placa.",
        diu: ['Aquesta idea, la podries fer amb quatre o cinc formes?|Esta idea, ¿la podrías hacer con cuatro o cinco formas?', "Aquest requisit té un número? Com sabrem si es compleix?|¿Este requisito tiene un número? ¿Cómo sabremos si se cumple?"], slides: ['s8'], app: 'Encara no: la fitxa del projecte.|Todavía no: la ficha del proyecto.', org: "Individual, amb parelles per explicar-se l'encàrrec|Individual, con parejas para explicarse el encargo" },
      { min: 17, t: "A l'ordinador: del paper al taller|En el ordenador: del papel al taller", fase: 'ordinador', fa: "Fan la sessió a l'app: la vista de dalt, els forats del test, el rètol que fa massa alt el test i els tres reptes (les mides de l'esbós, buidar-lo amb parets de 3 mm i enganxar l'etiqueta perquè càpiga en 80 × 80 × 60 mm).|Hacen la sesión en la app: la vista de arriba, los agujeros de la maceta, el letrero que hace demasiado alta la maceta y los tres retos (las medidas del boceto, vaciarla con paredes de 3 mm y pegar la etiqueta para que quepa en 80 × 80 × 60 mm).",
        diu: ["Quin requisit de la Jana revisa aquesta comprovació?|¿Qué requisito de Jana revisa esta comprobación?", "Per què el forat fa 54 mm si el test en fa 60?|¿Por qué el agujero mide 54 mm si la maceta mide 60?"], slides: ['s9', 's10', 's11'], app: "Sessió «La idea», fins a «La versió 1 del teu disseny».|Sesión «La idea», hasta «La versión 1 de tu diseño».", org: 'Individual|Individual' },
      { min: 8, t: 'La versió 1|La versión 1', fase: 'crea', fa: "Cada alumne/a posa a la placa les formes principals del seu esbós amb les mides de la fitxa i la desa. No cal cap detall: la sessió que ve continuarà des d'aquí.|Cada alumno/a pone en la placa las formas principales de su boceto con las medidas de la ficha y la guarda. No hace falta ningún detalle: la sesión que viene continuará desde aquí.",
        diu: ["Quina és la forma més gran del teu invent? Quines mides té a la fitxa?|¿Cuál es la forma más grande de tu invento? ¿Qué medidas tiene en la ficha?"], slides: ['s12'], app: "Pas «La versió 1 del teu disseny».|Paso «La versión 1 de tu diseño».", org: 'Individual|Individual' },
      { min: 6, t: 'Tancament|Cierre', fase: 'tancament', fa: "Repassa les tres peces de la idea i recull les fitxes en una carpeta per a la sessió que ve. Tiquet de sortida i proposta per a casa.|Repasa las tres piezas de la idea y recoge las fichas en una carpeta para la sesión que viene. Ticket de salida y propuesta para casa.",
        diu: ["Digues el teu encàrrec en una sola frase.|Di tu encargo en una sola frase."], slides: ['s13', 's14', 's15'], app: "Les últimes preguntes de la sessió i «Com t'ha anat?».|Las últimas preguntas de la sesión y «¿Cómo te ha ido?».", org: 'Tot el grup|Todo el grupo' }
    ],
    errors: [["Tria una idea massa gran o complicada (una casa sencera, un cotxe amb motor).|Elige una idea demasiado grande o complicada (una casa entera, un coche con motor).", "Pregunta-li quina part d'aquella idea seria útil sola i si cap a la placa (180 × 180 × 150 mm). Millor un objecte senzill i ben acabat.|Pregúntale qué parte de esa idea sería útil sola y si cabe en la placa (180 × 180 × 150 mm). Mejor un objeto sencillo y bien acabado."],
      ["Escriu requisits que no es poden comprovar («que sigui xulo», «que agradi»).|Escribe requisitos que no se pueden comprobar («que sea chulo», «que guste»).", "Ajuda'l a afegir-hi un número o una acció: «com a molt 100 mm», «aguanta tres llapis», «parets de 3 mm».|Ayúdale a añadir un número o una acción: «como mucho 100 mm», «aguanta tres lápices», «paredes de 3 mm»."],
      ["Dibuixa l'esbós en perspectiva i sense cotes.|Dibuja el boceto en perspectiva y sin cotas.", "Demana-li dues vistes planes (davant i dalt) i, a cada vista, les mides que es veuen: amplada i alçada a davant; amplada i fondària a dalt.|Pídele dos vistas planas (delante y arriba) y, en cada vista, las medidas que se ven: anchura y altura delante; anchura y fondo arriba."],
      ["Al repte del buit, posa el forat a z = 0 i el test es queda sense fons.|En el reto del hueco, pone el agujero en z = 0 y la maceta se queda sin fondo.", "Que miri la comprovació «El fons és sencer» i la vista de davant amb «Resultat»: el forat ha de començar a z = 3.|Que mire la comprobación «El fondo está entero» y la vista de delante con «Resultado»: el agujero tiene que empezar en z = 3."]],
    diff: { mes: "Escriure cinc requisits (dos de mides, un d'ús, un de material i un d'impressió) i afegir una tercera vista (de costat) a l'esbós. A l'app, provar de modelar les formes principals d'una segona idea.|Escribir cinco requisitos (dos de medidas, uno de uso, uno de material y uno de impresión) y añadir una tercera vista (de lado) al boceto. En la app, probar a modelar las formas principales de una segunda idea.",
      menys: "Partir d'un invent de la unitat 7 o del test de la Jana i canviar-ne només les mides i la persona. Escriure l'encàrrec amb les frases d'inici de la fitxa.|Partir de un invento de la unidad 7 o de la maceta de Jana y cambiar solo sus medidas y la persona. Escribir el encargo con las frases de inicio de la ficha." },
    aval: { ticket: ["Digues el teu encàrrec: per a qui és i quin problema resol.|Di tu encargo: para quién es y qué problema resuelve.", "Digues un requisit del teu disseny que tingui un número.|Di un requisito de tu diseño que tenga un número."],
      rubric: [["L'encàrrec|El encargo", "Diu clarament per a qui és, quin problema resol i on es farà servir.|Dice claramente para quién es, qué problema resuelve y dónde se usará.", "Descriu l'objecte, però no diu per a qui és o per a què serveix.|Describe el objeto, pero no dice para quién es o para qué sirve."],
        ['Els requisits|Los requisitos', "Escriu requisits comprovables, amb números (mides, ús, material, impressió).|Escribe requisitos comprobables, con números (medidas, uso, material, impresión).", 'Escriu desitjos generals que no es poden comprovar.|Escribe deseos generales que no se pueden comprobar.'],
        ["L'esbós i la v1|El boceto y la v1", "Fa dues vistes amb cotes i les passa al taller amb les mides correctes.|Hace dos vistas con cotas y las pasa al taller con las medidas correctas.", "Dibuixa l'objecte, però sense cotes o amb mides que no coincideixen amb el model.|Dibuja el objeto, pero sin cotas o con medidas que no coinciden con el modelo."]] },
    casa: "Explica el teu encàrrec a algú de casa i pregunta-li si l'objecte l'ajudaria. Si et dona una idea nova, apunta-la a la fitxa.|Explica tu encargo a alguien de casa y pregúntale si el objeto le ayudaría. Si te da una idea nueva, apúntala en la ficha.",
    intro: "Comença el projecte final del curs. En aquesta primera sessió no es modela gaire: el que compta és que cada alumne/a tingui una idea que pugui acabar, un encàrrec clar, uns requisits que es puguin comprovar i un esbós amb cotes. Tota la feina de les sessions següents surt d'aquesta fitxa.|Empieza el proyecto final del curso. En esta primera sesión no se modela mucho: lo que cuenta es que cada alumno/a tenga una idea que pueda acabar, un encargo claro, unos requisitos que se puedan comprobar y un boceto con cotas. Todo el trabajo de las sesiones siguientes sale de esta ficha.",
    claus: ["L'encàrrec respon tres preguntes: per a qui, quin problema i on.|El encargo responde tres preguntas: para quién, qué problema y dónde.", "Un requisit és útil si es pot comprovar: amb un número, amb el regle o amb una comprovació de l'app.|Un requisito es útil si se puede comprobar: con un número, con la regla o con una comprobación de la app.",
      "L'esbós de dues vistes amb cotes és el plànol del model.|El boceto de dos vistas con cotas es el plano del modelo.", "Una idea senzilla i acabada val més que una de gegant a mig fer.|Una idea sencilla y acabada vale más que una gigante a medio hacer."],
    prev: ["Haver fet la unitat 7 (entrevista, esbós amb mides i especificacions).|Haber hecho la unidad 7 (entrevista, boceto con medidas y especificaciones).", "Saber canviar mides i posicions amb els camps numèrics.|Saber cambiar medidas y posiciones con los campos numéricos.", "Conèixer les vistes de davant, de dalt i de costat (unitat 1).|Conocer las vistas de delante, de arriba y de lado (unidad 1)."],
    faq: [["Poden fer el mateix invent de la unitat 7?|¿Pueden hacer el mismo invento de la unidad 7?", "Sí, si en fan una versió millor o per a una altra persona: l'important és que escriguin un encàrrec i uns requisits nous.|Sí, si hacen una versión mejor o para otra persona: lo importante es que escriban un encargo y unos requisitos nuevos."],
      ["I si un alumne/a no sap què inventar?|¿Y si un alumno/a no sabe qué inventar?", "Proposa-li les idees de la classe (penjador, organitzador, test, clauer, porta-mòbil…) i que triï per a qui el faria. Pensar en una persona concreta desbloqueja la idea.|Propónle las ideas de la clase (colgador, organizador, maceta, llavero, soporte de móvil…) y que elija para quién lo haría. Pensar en una persona concreta desbloquea la idea."],
      ["Es desa el disseny d'una sessió a l'altra?|¿Se guarda el diseño de una sesión a otra?", "Sí. Quan l'alumne/a desa el projecte al pas de crear, la sessió següent comença amb aquesta versió. Si un dia no en desa cap, l'app li proposa el test de la Jana per continuar.|Sí. Cuando el alumno/a guarda el proyecto en el paso de crear, la sesión siguiente empieza con esa versión. Si un día no guarda ninguno, la app le propone la maceta de Jana para continuar."]],
    tec: [["Al pas de la versió 1 no s'activa el botó de desar.|En el paso de la versión 1 no se activa el botón de guardar.", "Calen almenys dues peces, que toquin la placa i que tot càpiga en 180 × 180 × 150 mm. Mireu quina comprovació no està marcada.|Hacen falta al menos dos piezas, que toquen la placa y que todo quepa en 180 × 180 × 150 mm. Mirad qué comprobación no está marcada."],
      ["Al repte de l'etiqueta, «És una sola peça» no es marca.|En el reto de la etiqueta, «Es una sola pieza» no se marca.", "L'etiqueta ha de ficar-se una mica dins de la paret: amb y = −30 s'hi fica 2 mm. Si només toca, no compta com una sola peça.|La etiqueta tiene que meterse un poco dentro de la pared: con y = −30 se mete 2 mm. Si solo toca, no cuenta como una sola pieza."],
      ["Al repte de la vista de dalt no es pot girar el model.|En el reto de la vista de arriba no se puede girar el modelo.", "És a propòsit: la vista està bloquejada perquè l'alumnat reconegui la planta. Als altres passos sí que es pot girar.|Es a propósito: la vista está bloqueada para que el alumnado reconozca la planta. En los demás pasos sí se puede girar."]],
    extra: ["Fer un mural «Idees per a la fira» amb els encàrrecs de tota la classe i agrupar-los per a qui són (infants, avis, l'escola, animals…).|Hacer un mural «Ideas para la feria» con los encargos de toda la clase y agruparlos por para quién son (niños, abuelos, la escuela, animales…).", "Mesurar amb el regle el lloc on anirà l'invent (un ampit, un calaix, una prestatgeria) i fer-ne la mida màxima.|Medir con la regla el sitio donde irá el invento (un alféizar, un cajón, una estantería) y convertirlo en la medida máxima.", "Comparar l'esbós amb el d'un company/a: entendríeu el seu invent sense que us l'expliqués?|Comparar el boceto con el de un compañero/a: ¿entenderíais su invento sin que os lo explicara?"],
    trans: ["Sessió següent: modelar el disseny complet amb les eines del curs, a partir de la versió 1.|Sesión siguiente: modelar el diseño completo con las herramientas del curso, a partir de la versión 1.", "Tecnologia: el procés tecnològic comença per la necessitat i les especificacions.|Tecnología: el proceso tecnológico empieza por la necesidad y las especificaciones."],
    slides: [
      { id: 's1', k: 'portada', t: 'La idea|La idea', x: "El meu disseny per a la Fira d'Invents|Mi diseño para la Feria de Inventos", nota: "Presenta el projecte final i la fira: cada alumne/a hi portarà un disseny propi.|Presenta el proyecto final y la feria: cada alumno/a llevará un diseño propio." },
      { id: 's2', k: 'pregunta', t: 'Què inventaries?|¿Qué inventarías?', x: "Pensa en algú que coneguis: què li costa o li fa nosa cada dia?|Piensa en alguien que conozcas: ¿qué le cuesta o le molesta cada día?", nota: "Recull idees a la pissarra sense jutjar-les: després cadascú en triarà una.|Recoge ideas en la pizarra sin juzgarlas: después cada uno elegirá una." },
      { id: 's3', k: 'anim', t: 'El projecte final|El proyecto final', anim: 'm8road', x: 'La idea · modelar · revisar · presentar|La idea · modelar · revisar · presentar', nota: "Relaciona cada parada amb una sessió. Remarca que cada sessió es desa una versió.|Relaciona cada parada con una sesión. Remarca que cada sesión se guarda una versión." },
      { id: 's4', k: 'anim', t: "L'encàrrec|El encargo", anim: 'm8brief', x: 'Per a qui · quin problema · on|Para quién · qué problema · dónde', nota: "Llegiu l'encàrrec de la Jana i feu-ne un entre tots per a un altre objecte.|Leed el encargo de Jana y haced uno entre todos para otro objeto." },
      { id: 's5', k: 'media', t: 'Els requisits de la Jana|Los requisitos de Jana', x: 'Com a molt 80 × 80 × 60 mm · forats · nanses · parets de 3 mm|Como mucho 80 × 80 × 60 mm · agujeros · asas · paredes de 3 mm', media: { k: 'model', model: JANA }, nota: "Gira el test i demana quina part respon cada requisit.|Gira la maceta y pide qué parte responde a cada requisito." },
      { id: 's6', k: 'concepte', t: 'Requisits que es poden comprovar|Requisitos que se pueden comprobar', x: "«Fa com a molt 80 mm» sí · «És xulo» no. Mides, ús, material i impressió, amb números.|«Mide como mucho 80 mm» sí · «Es chulo» no. Medidas, uso, material e impresión, con números.", nota: "Feu entre tots la prova: com comprovaríeu cada requisit?|Haced entre todos la prueba: ¿cómo comprobaríais cada requisito?" },
      { id: 's7', k: 'anim', t: "L'esbós amb cotes|El boceto con cotas", anim: 'm8esbos', x: 'De davant i de dalt · cada cota, un número del taller|De delante y de arriba · cada cota, un número del taller', nota: "Mostra com la cota de 60 es converteix en la X i la Y, i la de 56, en la Z.|Muestra cómo la cota de 60 se convierte en la X y la Y, y la de 56, en la Z." },
      { id: 's8', k: 'activitat', t: 'La fitxa del meu projecte|La ficha de mi proyecto', timer: 12, punts: ['Tres idees i una de triada|Tres ideas y una elegida', 'Encàrrec: per a qui, problema, on|Encargo: para quién, problema, dónde', 'Tres requisits amb números|Tres requisitos con números', 'Esbós de davant i de dalt amb cotes|Boceto de delante y de arriba con cotas'], nota: "Individual. A meitat del temps, que expliquin l'encàrrec al company/a del costat.|Individual. A mitad del tiempo, que expliquen el encargo al compañero/a de al lado." },
      { id: 's9', k: 'media', t: 'La primera idea de la Jana|La primera idea de Jana', x: 'Amb el rètol, el test fa 89 mm d\'alt: no compleix «com a molt 60 mm».|Con el letrero, la maceta mide 89 mm de alto: no cumple «como mucho 60 mm».', media: { k: 'model', model: IDEA0 }, nota: "Serveix per als qui s'encallin al pas de trobar la peça que no compleix el requisit.|Sirve para quien se atasque en el paso de encontrar la pieza que no cumple el requisito." },
      { id: 's10', k: 'repte', t: "A l'ordinador|En el ordenador", punts: ["Les mides de l'esbós: 60 × 60 × 56 mm.|Las medidas del boceto: 60 × 60 × 56 mm.", 'Buidar-lo amb parets i fons de 3 mm.|Vaciarla con paredes y fondo de 3 mm.', "Enganxar l'etiqueta: com a molt 80 × 80 × 60 mm.|Pegar la etiqueta: como mucho 80 × 80 × 60 mm."], nota: "Abans de cada repte, que llegeixin quin requisit revisa.|Antes de cada reto, que lean qué requisito revisa." },
      { id: 's11', k: 'media', t: 'De l\'esbós al model|Del boceto al modelo', x: 'Un cilindre de 60 × 60 × 56 mm i un forat de 54 mm a z = 3.|Un cilindro de 60 × 60 × 56 mm y un agujero de 54 mm en z = 3.', media: { k: 'model', model: { parts: V1 }, view: 'front' }, nota: "Mostra amb «Resultat» que el fons de 3 mm queda sencer.|Muestra con «Resultado» que el fondo de 3 mm queda entero." },
      { id: 's12', k: 'repte', t: 'La versió 1 del teu disseny|La versión 1 de tu diseño', punts: ['Les formes grans de l\'esbós.|Las formas grandes del boceto.', 'Les mides de la fitxa.|Las medidas de la ficha.', 'Desa-la: la continuaràs.|Guárdala: la continuarás.'], nota: "Remarca que no cal cap detall: la v1 és només l'esquelet.|Remarca que no hace falta ningún detalle: la v1 es solo el esqueleto." },
      { id: 's13', k: 'resum', t: 'Avui hem après…|Hoy hemos aprendido…', punts: ["L'encàrrec: per a qui, quin problema i on.|El encargo: para quién, qué problema y dónde.", 'Requisits amb números que es poden comprovar.|Requisitos con números que se pueden comprobar.', "L'esbós de dues vistes amb cotes.|El boceto de dos vistas con cotas."], nota: 'Llegiu-ho junts.|Leedlo juntos.' },
      { id: 's14', k: 'tiquet', t: 'Tiquet de sortida|Ticket de salida', punts: ['El teu encàrrec en una frase.|Tu encargo en una frase.', 'Un requisit amb un número.|Un requisito con un número.'], nota: 'Oral, abans de sortir.|Oral, antes de salir.' },
      { id: 's15', k: 'concepte', t: 'A casa|En casa', x: "Explica el teu encàrrec a algú de casa i pregunta-li si l'objecte l'ajudaria.|Explica tu encargo a alguien de casa y pregúntale si el objeto le ayudaría.", nota: 'Proposta opcional.|Propuesta opcional.' }
    ],
    print: [{ id: 'p1', t: 'Fitxa del meu projecte|Ficha de mi proyecto', k: 'fitxa', intro: "La faràs servir les quatre sessions del projecte. Escriu poc i clar, i guarda-la a la carpeta.|La usarás las cuatro sesiones del proyecto. Escribe poco y claro, y guárdala en la carpeta.",
      items: [{ q: 'Tres idees: 1) ____ 2) ____ 3) ____ · Encercla la que faràs.|Tres ideas: 1) ____ 2) ____ 3) ____ · Rodea la que harás.', sol: "Resposta oberta: valoreu que la idea triada es pugui fer en dues sessions.|Respuesta abierta: valorad que la idea elegida se pueda hacer en dos sesiones." },
        { q: "Encàrrec: és per a ____ · resol ____ · es farà servir a ____|Encargo: es para ____ · resuelve ____ · se usará en ____", sol: "Per exemple: per als infants de P4 · les plantes no tenen test · a la finestra de la classe.|Por ejemplo: para los niños de P4 · las plantas no tienen maceta · en la ventana de la clase." },
        { q: 'Requisits (amb números): mides màximes ____ · ús ____ · material i impressió ____|Requisitos (con números): medidas máximas ____ · uso ____ · material e impresión ____', sol: "Per exemple: com a molt 80 × 80 × 60 mm · forats perquè surti l'aigua · PLA, parets de 3 mm, base plana.|Por ejemplo: como mucho 80 × 80 × 60 mm · agujeros para que salga el agua · PLA, paredes de 3 mm, base plana." },
        { q: "Esbós de davant i de dalt amb les cotes en mm.|Boceto de delante y de arriba con las cotas en mm.", sol: "Dues vistes planes amb amplada, fondària i alçada.|Dos vistas planas con anchura, fondo y altura." },
        { q: 'Les formes principals que faré servir: ____|Las formas principales que usaré: ____', sol: "Per exemple: un cilindre i un forat rodó.|Por ejemplo: un cilindro y un agujero redondo." }] }]
  },
  /* ---------- Sessió 2 · Modelar-lo ---------- */
  'm8-2': {
    obj: ["L'alumne/a planifica l'ordre de construcció del seu model: formes grans, forats, detalls i comprovació.|El alumno/a planifica el orden de construcción de su modelo: formas grandes, agujeros, detalles y comprobación.",
      "L'alumne/a fa servir les eines del curs (Duplica, Mirall, Gir, Forat i els camps en mm) per construir amb precisió.|El alumno/a usa las herramientas del curso (Duplica, Espejo, Giro, Agujero y los campos en mm) para construir con precisión.",
      "L'alumne/a reconeix i construeix parts simètriques amb Duplica i Mirall.|El alumno/a reconoce y construye partes simétricas con Duplica y Espejo.",
      "L'alumne/a continua la seva versió 1 i en desa la versió 2 completa.|El alumno/a continúa su versión 1 y guarda la versión 2 completa."],
    comp: ["Tecnologia i digitalització: disseny assistit per ordinador (CAD 3D) i planificació d'un procés|Tecnología y digitalización: diseño asistido por ordenador (CAD 3D) y planificación de un proceso",
      "Matemàtiques, sentit espacial: simetria respecte d'un eix i girs de 90°|Matemáticas, sentido espacial: simetría respecto a un eje y giros de 90°",
      "Matemàtiques, sentit de la mesura: posicions i mides en mil·límetres; repetir amb un pas constant|Matemáticas, sentido de la medida: posiciones y medidas en milímetros; repetir con un paso constante",
      "Pensament computacional: descompondre un objecte en parts i ordenar els passos per construir-lo|Pensamiento computacional: descomponer un objeto en partes y ordenar los pasos para construirlo"],
    vocab: [['Pla de construcció|Plan de construcción', "La llista ordenada de les peces que es faran, amb les seves mides.|La lista ordenada de las piezas que se harán, con sus medidas."],
      ['Drenatge|Drenaje', "Forats al fons d'un test perquè l'aigua que sobra pugui sortir.|Agujeros en el fondo de una maceta para que el agua que sobra pueda salir."],
      ['Pas (en duplicar)|Paso (al duplicar)', "La distància entre una còpia i la següent.|La distancia entre una copia y la siguiente."],
      ['Simètric|Simétrico', "Que una meitat és el reflex de l'altra, com en un mirall.|Que una mitad es el reflejo de la otra, como en un espejo."],
      ['Versió|Versión', "Cada estat desat d'un disseny (v1, v2, v3) per poder-lo continuar i comparar.|Cada estado guardado de un diseño (v1, v2, v3) para poder continuarlo y compararlo."],
      ['Relleu|Relieve', "Una forma que sobresurt d'una superfície, com el cor de l'etiqueta.|Una forma que sobresale de una superficie, como el corazón de la etiqueta."]],
    mat: { aula: ["Un ordinador per alumne/a amb Numi Tech obert a la sessió «Modelar-lo»|Un ordenador por alumno/a con Numi Tech abierto en la sesión «Modelarlo»", 'Projector i la presentació de la sessió|Proyector y la presentación de la sesión', "La fitxa del projecte de la sessió passada i la del pla de construcció|La ficha del proyecto de la sesión pasada y la del plan de construcción"],
      imprimir: ['El pla de construcció|El plan de construcción'],
      prep: ["Retornar a cada alumne/a la seva fitxa del projecte (encàrrec, requisits i esbós).|Devolver a cada alumno/a su ficha del proyecto (encargo, requisitos y boceto).", "Comprovar que tothom té desada la versió 1: si algú no la té, començarà amb la v1 de la Jana i la pot transformar en el seu disseny.|Comprobar que todo el mundo tiene guardada la versión 1: si alguien no la tiene, empezará con la v1 de Jana y la puede transformar en su diseño.", "Provar abans el repte de les nanses: Duplica, Mirall → Esquerra ↔ dreta i x = −33.|Probar antes el reto de las asas: Duplica, Espejo → Izquierda ↔ derecha y x = −33."] },
    plan: [
      { min: 5, t: 'La caixa d\'eines|La caja de herramientas', fase: 'inici', fa: "Recorda on es va quedar cada projecte (la versió 1) i fes les preguntes de repàs: com es fa un forat que travessa i què fa el Mirall. Explica que avui toca modelar el disseny complet.|Recuerda dónde se quedó cada proyecto (la versión 1) y haz las preguntas de repaso: cómo se hace un agujero que atraviesa y qué hace el Espejo. Explica que hoy toca modelar el diseño completo.",
        diu: ['Quines eines del taller recordeu? Per a què serveix cadascuna?|¿Qué herramientas del taller recordáis? ¿Para qué sirve cada una?'], slides: ['s1', 's2'], app: 'Encara no: pantalles abaixades.|Todavía no: pantallas bajadas.', org: 'Tot el grup|Todo el grupo' },
      { min: 10, t: 'Modelar per ordre|Modelar por orden', fase: 'teoria', fa: "Explica l'ordre de construcció amb el test de la Jana (formes grans, forats, detalls, comprovació), repassa la caixa d'eines amb la unitat on es va aprendre cada una i mostra el test acabat en 3D: per a què serveix cada detall. Explica que cada versió desada es continua la sessió següent.|Explica el orden de construcción con la maceta de Jana (formas grandes, agujeros, detalles, comprobación), repasa la caja de herramientas con la unidad donde se aprendió cada una y muestra la maceta acabada en 3D: para qué sirve cada detalle. Explica que cada versión guardada se continúa la sesión siguiente.",
        diu: ['Per què no comencem pels detalls?|¿Por qué no empezamos por los detalles?', 'Quina eina faríeu servir per fer dues nanses iguals però mirant a costats oposats?|¿Qué herramienta usaríais para hacer dos asas iguales pero mirando a lados opuestos?'], slides: ['s3', 's4', 's5', 's6'], app: "Encara no: tota l'atenció a la projecció.|Todavía no: toda la atención en la proyección.", org: 'Tot el grup|Todo el grupo' },
      { min: 8, t: 'El pla de construcció|El plan de construcción', fase: 'desconnectat', fa: "Cada alumne/a numera les peces del seu esbós en ordre, n'escriu la forma i les mides i marca les que es repeteixen o són simètriques. Després ho explica al company/a.|Cada alumno/a numera las piezas de su boceto en orden, escribe su forma y medidas y marca las que se repiten o son simétricas. Después lo explica al compañero/a.",
        diu: ['Quina peça faràs primer? Per què?|¿Qué pieza harás primero? ¿Por qué?', 'Hi ha alguna peça que es repeteixi? Quin pas tindrà?|¿Hay alguna pieza que se repita? ¿Qué paso tendrá?'], slides: ['s7'], app: 'Encara no: el pla de construcció.|Todavía no: el plan de construcción.', org: 'Individual i per parelles|Individual y por parejas' },
      { min: 20, t: "A l'ordinador: el test pas a pas|En el ordenador: la maceta paso a paso", fase: 'ordinador', fa: "Fan la sessió a l'app: la nansa feta amb Mirall, trobar la nansa que no és simètrica i els reptes del test (el drenatge amb Duplica, les nanses amb Mirall i el cor dret amb Gir). Els reptes són el mateix camí que faran amb el seu disseny.|Hacen la sesión en la app: el asa hecha con Espejo, encontrar el asa que no es simétrica y los retos de la maceta (el drenaje con Duplica, las asas con Espejo y el corazón de pie con Giro). Los retos son el mismo camino que harán con su diseño.",
        diu: ['Quina x té cada forat? Quina distància hi ha entre l\'un i l\'altre?|¿Qué x tiene cada agujero? ¿Qué distancia hay entre uno y otro?', 'Després del Mirall, on és la nansa nova? Què li falta?|Después del Espejo, ¿dónde está el asa nueva? ¿Qué le falta?'], slides: ['s8', 's9', 's10', 's11'], app: "Sessió «Modelar-lo», fins a «La versió 2 del teu disseny».|Sesión «Modelarlo», hasta «La versión 2 de tu diseño».", org: 'Individual|Individual' },
      { min: 12, t: 'La versió 2|La versión 2', fase: 'crea', fa: "Cada alumne/a continua la seva versió 1 seguint el seu pla: forats, detalls i una comprovació final amb les vistes i el regle. Abans de desar, comprova que les mides són les de la fitxa.|Cada alumno/a continúa su versión 1 siguiendo su plan: agujeros, detalles y una comprobación final con las vistas y la regla. Antes de guardar, comprueba que las medidas son las de la ficha.",
        diu: ['Quina eina has fet servir per a aquesta part?|¿Qué herramienta has usado para esta parte?', "Aquestes dues peces es fiquen l'una dins de l'altra?|¿Estas dos piezas se meten una dentro de la otra?"], slides: ['s12'], app: "Pas «La versió 2 del teu disseny».|Paso «La versión 2 de tu diseño».", org: 'Individual|Individual' },
      { min: 5, t: 'Tancament|Cierre', fase: 'tancament', fa: "Repassa l'ordre de construcció i les eines que han fet servir. Tiquet de sortida i proposta per a casa.|Repasa el orden de construcción y las herramientas que han usado. Ticket de salida y propuesta para casa.",
        diu: ["Quina eina t'ha estalviat més feina avui?|¿Qué herramienta te ha ahorrado más trabajo hoy?"], slides: ['s13', 's14', 's15'], app: "Les últimes preguntes i «Com t'ha anat?».|Las últimas preguntas y «¿Cómo te ha ido?».", org: 'Tot el grup|Todo el grupo' }
    ],
    errors: [["Al drenatge, duplica dues vegades seguides i la tercera còpia surt al lloc equivocat.|En el drenaje, duplica dos veces seguidas y la tercera copia sale en el sitio equivocado.", "Que posi la primera còpia a x = 0 (a Posició) abans de tornar a duplicar: la següent repeteix aquest salt i surt sola a x = 12. També pot escriure la x de cada còpia.|Que ponga la primera copia en x = 0 (en Posición) antes de volver a duplicar: la siguiente repite ese salto y sale sola en x = 12. También puede escribir la x de cada copia."],
      ["Fa la nansa esquerra amb Duplica però sense Mirall: el pendent queda cap amunt.|Hace el asa izquierda con Duplica pero sin Espejo: la pendiente queda hacia arriba.", "Que miri el test de davant i compari les dues nanses: el pendent ha d'anar a sota a totes dues. Mirall → Esquerra ↔ dreta ho arregla.|Que mire la maceta de delante y compare las dos asas: la pendiente tiene que ir debajo en las dos. Espejo → Izquierda ↔ derecha lo arregla."],
      ["Fa el Mirall i espera que la nansa passi sola a l'altre costat.|Hace el Espejo y espera que el asa pase sola al otro lado.", "Mirall → Esquerra ↔ dreta dona la volta a la peça al seu lloc: després cal escriure-li la x (−33) a Posició. Mirall → Còpia a l'altre costat (x) sí que la passa a l'altre costat.|Espejo → Izquierda ↔ derecha da la vuelta a la pieza en su sitio: después hay que escribirle la x (−33) en Posición. Espejo → Copia al otro lado (x) sí que la pasa al otro lado."],
      ["Gira el cor en y en lloc d'en x i queda de costat.|Gira el corazón en y en lugar de en x y queda de lado.", "Que miri el test de davant: el cor s'ha de veure dret. El gir és a la X, 90°.|Que mire la maceta de delante: el corazón se tiene que ver de pie. El giro es en la X, 90°."]],
    diff: { mes: "Fer el repte opcional del drenatge en creu i afegir al seu disseny un detall simètric fet amb Mirall i un patró fet amb Duplica.|Hacer el reto opcional del drenaje en cruz y añadir a su diseño un detalle simétrico hecho con Espejo y un patrón hecho con Duplica.",
      menys: "Fer els reptes amb la pista des del principi i, al seu disseny, afegir només els forats i un detall. Treballar amb el pla de construcció a la vista.|Hacer los retos con la pista desde el principio y, en su diseño, añadir solo los agujeros y un detalle. Trabajar con el plan de construcción a la vista." },
    aval: { ticket: ["Digues l'ordre per modelar un objecte.|Di el orden para modelar un objeto.", "Digues quina eina fas servir per fer dues peces simètriques.|Di qué herramienta usas para hacer dos piezas simétricas."],
      rubric: [['El pla|El plan', "Ordena les peces (grans, forats, detalls) i n'escriu les mides abans de modelar.|Ordena las piezas (grandes, agujeros, detalles) y escribe sus medidas antes de modelar.", "Modela sense pla i va canviant peces a ull.|Modela sin plan y va cambiando piezas a ojo."],
        ['Les eines|Las herramientas', "Tria l'eina adequada per a cada part (Duplica, Mirall, Gir, Forat) i escriu les posicions en mm.|Elige la herramienta adecuada para cada parte (Duplica, Espejo, Giro, Agujero) y escribe las posiciones en mm.", "Ho fa tot arrossegant i a ull, i les parts no queden exactes.|Lo hace todo arrastrando y a ojo, y las partes no quedan exactas."],
        ['La versió 2|La versión 2', "Continua la v1 i desa un model complet amb les mides de la fitxa.|Continúa la v1 y guarda un modelo completo con las medidas de la ficha.", "Desa un model a mig fer o que no segueix l'esbós.|Guarda un modelo a medio hacer o que no sigue el boceto."]] },
    casa: "Busca a casa un objecte simètric (una tassa, unes ulleres, una cadira) i un amb parts repetides (una pinta, un tren de rodes). Quina eina del taller faries servir per a cadascun?|Busca en casa un objeto simétrico (una taza, unas gafas, una silla) y uno con partes repetidas (un peine, un tren de ruedas). ¿Qué herramienta del taller usarías para cada uno?",
    intro: "Sessió de construcció. L'alumnat torna a la seva versió 1 i la completa seguint un pla: primer practica amb el test de la Jana el mateix camí que farà amb el seu disseny (forats amb Duplica, simetria amb Mirall i un detall girat), i després ho aplica al seu invent. És la sessió que reuneix més eines del curs.|Sesión de construcción. El alumnado vuelve a su versión 1 y la completa siguiendo un plan: primero practica con la maceta de Jana el mismo camino que hará con su diseño (agujeros con Duplica, simetría con Espejo y un detalle girado), y después lo aplica a su invento. Es la sesión que reúne más herramientas del curso.",
    claus: ["Es modela per ordre: formes grans, forats, detalls i comprovació.|Se modela por orden: formas grandes, agujeros, detalles y comprobación.", "Cada eina té una feina: Duplica repeteix, Mirall reflecteix, Gir posa dret, Forat resta.|Cada herramienta tiene un trabajo: Duplica repite, Espejo refleja, Giro pone de pie, Agujero resta.",
      "Les peces que han d'anar juntes es fiquen 1 o 2 mm l'una dins de l'altra.|Las piezas que tienen que ir juntas se meten 1 o 2 mm una dentro de la otra.", "La versió desada es continua la sessió següent: el projecte creix sense començar de zero.|La versión guardada se continúa la sesión siguiente: el proyecto crece sin empezar de cero."],
    prev: ["Haver desat la versió 1 a la sessió «La idea».|Haber guardado la versión 1 en la sesión «La idea».", "Saber fer servir Duplica i Mirall (unitat 4) i els forats (unitat 5).|Saber usar Duplica y Espejo (unidad 4) y los agujeros (unidad 5).", "Saber girar una peça 90° a la X (unitat 3).|Saber girar una pieza 90° en la X (unidad 3)."],
    faq: [["Per què les nanses de la Jana són falques cap per avall?|¿Por qué las asas de Jana son cuñas boca abajo?", "Perquè per sota fan pendent i la Nuvi les pot imprimir sense suports (voladissos de menys de 45°, unitat 6). Una nansa amb la cara de sota plana i a l'aire necessitaria suports.|Porque por debajo hacen pendiente y Nuvi las puede imprimir sin soportes (voladizos de menos de 45°, unidad 6). Un asa con la cara de abajo plana y en el aire necesitaría soportes."],
      ["Un alumne/a vol canviar d'idea a mitja sessió. Pot?|Un alumno/a quiere cambiar de idea a media sesión. ¿Puede?", "Pot, però que actualitzi la fitxa (encàrrec, requisits i esbós) abans de modelar. Si el temps és just, millor que millori la idea que ja té.|Puede, pero que actualice la ficha (encargo, requisitos y boceto) antes de modelar. Si el tiempo es justo, mejor que mejore la idea que ya tiene."],
      ["El seu disseny no té res simètric ni repetit. Ha de fer servir Duplica o Mirall igualment?|Su diseño no tiene nada simétrico ni repetido. ¿Tiene que usar Duplica o Espejo igualmente?", "No és obligatori. El criteri demana dues eines del curs: poden ser Forat, Gir, Alinea o els camps en mm.|No es obligatorio. El criterio pide dos herramientas del curso: pueden ser Agujero, Giro, Alinea o los campos en mm."]],
    tec: [["La versió 2 comença buida o amb el test de la Jana.|La versión 2 empieza vacía o con la maceta de Jana.", "Vol dir que no hi ha cap versió 1 desada en aquest perfil. Pot partir del test de la Jana o esborrar-lo i tornar a fer les formes de la seva fitxa.|Quiere decir que no hay ninguna versión 1 guardada en este perfil. Puede partir de la maceta de Jana o borrarla y volver a hacer las formas de su ficha."],
      ["La comprovació de simetria no es marca, tot i que les nanses semblen iguals.|La comprobación de simetría no se marca, aunque las asas parecen iguales.", "La simetria ha de ser exacta: la nansa esquerra ha d'estar a x = −33 i a la mateixa alçada que la dreta. Revisa la Posició.|La simetría tiene que ser exacta: el asa izquierda tiene que estar en x = −33 y a la misma altura que la derecha. Revisa la Posición."],
      ["El cor no es veu davant de l'etiqueta.|El corazón no se ve delante de la etiqueta.", "Comproveu el gir (x = 90) i la posició y = −33. Amb la vista de davant s'hauria de veure dret i enganxat a l'etiqueta.|Comprobad el giro (x = 90) y la posición y = −33. Con la vista de delante se debería ver de pie y pegado a la etiqueta."]],
    extra: ["Fer una «caça d'eines»: buscar objectes de l'aula i dir quina eina del taller faria servir cadascun (Mirall, Duplica, Forat…).|Hacer una «caza de herramientas»: buscar objetos del aula y decir qué herramienta del taller usaría cada uno (Espejo, Duplica, Agujero…).", "Comparar la v1 i la v2 del propi disseny al portafoli i escriure què ha canviat.|Comparar la v1 y la v2 del propio diseño en el portafolio y escribir qué ha cambiado.", "Proposar un patró de forats diferent per al test (en cercle, en creu, en quadrícula) i dibuixar-lo de dalt.|Proponer un patrón de agujeros diferente para la maceta (en círculo, en cruz, en cuadrícula) y dibujarlo desde arriba."],
    trans: ["Sessió següent: revisar el disseny amb les quatre proves de la Nuvi i amb la revisió d'un company/a.|Sesión siguiente: revisar el diseño con las cuatro pruebas de Nuvi y con la revisión de un compañero/a.", "Matemàtiques: la simetria i els patrons es troben a molts objectes de cada dia.|Matemáticas: la simetría y los patrones se encuentran en muchos objetos de cada día."],
    slides: [
      { id: 's1', k: 'portada', t: 'Modelar-lo|Modelarlo', x: 'De la versió 1 al disseny complet|De la versión 1 al diseño completo', nota: "Recorda el camí del projecte: avui és la parada 2.|Recuerda el camino del proyecto: hoy es la parada 2." },
      { id: 's2', k: 'repas', t: 'Recordem les eines|Recordamos las herramientas', punts: ['Un forat que travessa: més alt i començant per sota.|Un agujero que atraviesa: más alto y empezando por debajo.', 'Duplica: còpies amb el mateix pas.|Duplica: copias con el mismo paso.', 'Mirall: el reflex, com en un mirall.|Espejo: el reflejo, como en un espejo.'], nota: "Demana un exemple de cada eina fet durant el curs.|Pide un ejemplo de cada herramienta hecho durante el curso." },
      { id: 's3', k: 'anim', t: 'Per ordre|Por orden', anim: 'm8ordre', x: 'Formes grans · forats · detalls · comprovar|Formas grandes · agujeros · detalles · comprobar', nota: "Compara-ho amb construir una casa: primer les parets, després les finestres i al final les cortines.|Compáralo con construir una casa: primero las paredes, después las ventanas y al final las cortinas." },
      { id: 's4', k: 'anim', t: "La caixa d'eines|La caja de herramientas", anim: 'm8eines', x: 'Cada eina, la unitat on la vas aprendre.|Cada herramienta, la unidad donde la aprendiste.', nota: "Pregunta per a què serveix cada eina abans que surti a l'animació.|Pregunta para qué sirve cada herramienta antes de que salga en la animación." },
      { id: 's5', k: 'media', t: 'El test acabat|La maceta acabada', x: 'Forats, nanses i etiqueta: cada detall respon un requisit.|Agujeros, asas y etiqueta: cada detalle responde a un requisito.', media: { k: 'model', model: JANA }, nota: "Gira'l per sota per veure el pendent de les nanses: s'imprimeixen sense suports.|Gíralo por debajo para ver la pendiente de las asas: se imprimen sin soportes." },
      { id: 's6', k: 'anim', t: 'Versions|Versiones', anim: 'm8versio', x: 'v1 → v2 → v3: cada sessió continua la anterior.|v1 → v2 → v3: cada sesión continúa la anterior.', nota: "Remarca que cal desar al final de cada sessió.|Remarca que hay que guardar al final de cada sesión." },
      { id: 's7', k: 'activitat', t: 'El pla de construcció|El plan de construcción', timer: 8, punts: ["Numera les peces de l'esbós en ordre.|Numera las piezas del boceto en orden.", 'Forma i mides de cada peça.|Forma y medidas de cada pieza.', 'Marca les repetides i les simètriques.|Marca las repetidas y las simétricas.'], nota: "Individual i, al final, explicació per parelles.|Individual y, al final, explicación por parejas." },
      { id: 's8', k: 'media', t: 'Duplica i Mirall|Duplica y Espejo', x: 'La nansa esquerra és el reflex de la dreta.|El asa izquierda es el reflejo de la derecha.', media: { k: 'model', model: { parts: V2 }, view: 'front' }, nota: "De davant es veu que totes dues tenen el pendent a sota.|De delante se ve que las dos tienen la pendiente debajo." },
      { id: 's9', k: 'repte', t: "A l'ordinador: el test pas a pas|En el ordenador: la maceta paso a paso", punts: ['El drenatge: tres forats amb Duplica.|El drenaje: tres agujeros con Duplica.', "Les nanses: Duplica, Mirall i x = −33.|Las asas: Duplica, Espejo y x = −33.", "El cor dret: Gir x = 90.|El corazón de pie: Giro x = 90."], nota: "Són els mateixos passos que faran amb el seu disseny.|Son los mismos pasos que harán con su diseño." },
      { id: 's10', k: 'media', t: 'El drenatge|El drenaje', x: 'Tres forats de 6 mm a x = −12, 0 i 12, de z = −1 a z = 5.|Tres agujeros de 6 mm en x = −12, 0 y 12, de z = −1 a z = 5.', media: { k: 'model', model: { parts: [...V1, ...DR] }, view: 'top' }, nota: "De dalt es veuen els tres forats al fons del test.|Desde arriba se ven los tres agujeros en el fondo de la maceta." },
      { id: 's11', k: 'concepte', t: 'Un truc per a tot el projecte|Un truco para todo el proyecto', x: "Les peces que van juntes, fica-les 1 o 2 mm l'una dins de l'altra.|Las piezas que van juntas, mételas 1 o 2 mm una dentro de la otra.", nota: "Avança'n la importància: a la sessió de revisió, «una sola peça» serà una de les quatre proves.|Adelanta su importancia: en la sesión de revisión, «una sola pieza» será una de las cuatro pruebas." },
      { id: 's12', k: 'repte', t: 'La versió 2 del teu disseny|La versión 2 de tu diseño', punts: ['Segueix el teu pla.|Sigue tu plan.', 'Fes servir almenys dues eines.|Usa al menos dos herramientas.', 'Comprova les mides i desa-la.|Comprueba las medidas y guárdala.'], nota: "Passa per les taules amb el pla de cada alumne/a a la mà.|Pasa por las mesas con el plan de cada alumno/a en la mano." },
      { id: 's13', k: 'resum', t: 'Avui hem après…|Hoy hemos aprendido…', punts: ['Modelar per ordre.|Modelar por orden.', 'Duplica, Mirall, Gir i Forat, cadascun per a la seva feina.|Duplica, Espejo, Giro y Agujero, cada uno para su trabajo.', 'Desar versions i continuar-les.|Guardar versiones y continuarlas.'], nota: 'Llegiu-ho junts.|Leedlo juntos.' },
      { id: 's14', k: 'tiquet', t: 'Tiquet de sortida|Ticket de salida', punts: ["L'ordre per modelar.|El orden para modelar.", "L'eina per a dues peces simètriques.|La herramienta para dos piezas simétricas."], nota: 'Oral, abans de sortir.|Oral, antes de salir.' },
      { id: 's15', k: 'concepte', t: 'A casa|En casa', x: "Busca un objecte simètric i un amb parts repetides. Quina eina faries servir per a cadascun?|Busca un objeto simétrico y uno con partes repetidas. ¿Qué herramienta usarías para cada uno?", nota: 'Proposta opcional.|Propuesta opcional.' }
    ],
    print: [{ id: 'p1', t: 'El pla de construcció|El plan de construcción', k: 'fitxa', intro: "Escriu les peces del teu disseny en l'ordre en què les faràs. Marca amb una estrella les repetides (Duplica) o simètriques (Mirall).|Escribe las piezas de tu diseño en el orden en que las harás. Marca con una estrella las repetidas (Duplica) o simétricas (Espejo).",
      items: [{ q: '1. Forma gran: ____ · mides x ____ y ____ z ____ mm|1. Forma grande: ____ · medidas x ____ y ____ z ____ mm', sol: 'Per exemple: cilindre · 60 × 60 × 56 mm.|Por ejemplo: cilindro · 60 × 60 × 56 mm.' },
        { q: '2. Forats: ____ · mides ____ · posició (x, y, z) ____|2. Agujeros: ____ · medidas ____ · posición (x, y, z) ____', sol: 'Per exemple: forat rodó de 54 mm a (0, 0, 3) i tres forats de 6 mm a x = −12, 0 i 12.|Por ejemplo: agujero redondo de 54 mm en (0, 0, 3) y tres agujeros de 6 mm en x = −12, 0 y 12.' },
        { q: '3. Detalls: ____ · mides ____ · eina (Duplica, Mirall, Gir…) ____|3. Detalles: ____ · medidas ____ · herramienta (Duplica, Espejo, Giro…) ____', sol: 'Per exemple: nanses de falca amb Mirall; un cor girat 90° a la X.|Por ejemplo: asas de cuña con Espejo; un corazón girado 90° en la X.' },
        { q: '4. Comprovació: quines vistes miraré i quines mides revisaré? ____|4. Comprobación: ¿qué vistas miraré y qué medidas revisaré? ____', sol: "Per exemple: davant (alçada), dalt (forats) i la mida màxima de la fitxa.|Por ejemplo: delante (altura), arriba (agujeros) y la medida máxima de la ficha." }] }]
  },
  /* ---------- Sessió 3 · Revisar-lo ---------- */
  'm8-3': {
    obj: ["L'alumne/a revisa si un disseny es pot imprimir amb les quatre proves: toca la placa, una sola peça, parets de 2 mm o més i cap a la placa.|El alumno/a revisa si un diseño se puede imprimir con las cuatro pruebas: toca la placa, una sola pieza, paredes de 2 mm o más y cabe en la placa.",
      "L'alumne/a arregla errors d'impressió habituals en models d'altres: parets primes, peces que floten i peces que només es toquen.|El alumno/a arregla errores de impresión habituales en modelos de otros: paredes finas, piezas que flotan y piezas que solo se tocan.",
      "L'alumne/a fa una revisió per parelles amb una rúbrica i dona dues estrelles i un desig concret.|El alumno/a hace una revisión por parejas con una rúbrica y da dos estrellas y un deseo concreto.",
      "L'alumne/a aplica la retroacció al seu disseny i en desa la versió 3, a punt per imprimir.|El alumno/a aplica la retroalimentación a su diseño y guarda la versión 3, a punto para imprimir."],
    comp: ["Tecnologia i digitalització: avaluació i millora d'un prototip; fabricació digital|Tecnología y digitalización: evaluación y mejora de un prototipo; fabricación digital",
      "Matemàtiques, sentit de la mesura: gruixos de paret i distàncies en mil·límetres|Matemáticas, sentido de la medida: grosores de pared y distancias en milímetros",
      "Comunicació oral i escrita: donar i rebre retroacció de manera amable i concreta|Comunicación oral y escrita: dar y recibir retroalimentación de manera amable y concreta",
      "Competència personal i social: avaluar la feina pròpia i la dels altres amb criteris compartits|Competencia personal y social: evaluar el trabajo propio y el de los demás con criterios compartidos"],
    vocab: [['Revisió|Revisión', "Mirar un disseny amb una llista de criteris per trobar què cal millorar abans de fabricar-lo.|Mirar un diseño con una lista de criterios para encontrar qué hay que mejorar antes de fabricarlo."],
      ['Rúbrica|Rúbrica', "Una taula amb criteris i nivells (aconseguit, a mig camí, encara no) per valorar una feina.|Una tabla con criterios y niveles (conseguido, a medio camino, todavía no) para valorar un trabajo."],
      ['Gruix de paret|Grosor de pared', "Quant fa una paret d'una peça. Al taller, com a mínim 2 mm.|Cuánto mide una pared de una pieza. En el taller, como mínimo 2 mm."],
      ['Peça solta|Pieza suelta', "Una part del model que no està enganxada a la resta: sortiria separada o a l'aire.|Una parte del modelo que no está pegada al resto: saldría separada o en el aire."],
      ['Revisió entre iguals|Revisión entre iguales', "Quan un company/a revisa la teva feina i tu revises la seva.|Cuando un compañero/a revisa tu trabajo y tú revisas el suyo."],
      ['Desig|Deseo', "Una proposta de millora concreta, dita amb amabilitat.|Una propuesta de mejora concreta, dicha con amabilidad."]],
    mat: { aula: ["Un ordinador per alumne/a amb Numi Tech obert a la sessió «Revisar-lo»|Un ordenador por alumno/a con Numi Tech abierto en la sesión «Revisarlo»", 'Projector i la presentació de la sessió|Proyector y la presentación de la sesión', "La rúbrica de revisió (una per alumne/a) i la fitxa del projecte|La rúbrica de revisión (una por alumno/a) y la ficha del proyecto"],
      imprimir: ['Rúbrica de revisió per parelles|Rúbrica de revisión por parejas'],
      prep: ["Fer les parelles de revisió abans de la classe: millor amb dissenys diferents i nivells semblants.|Hacer las parejas de revisión antes de la clase: mejor con diseños distintos y niveles parecidos.", "Imprimir una rúbrica per alumne/a: la farà servir per revisar el disseny del company/a.|Imprimir una rúbrica por alumno/a: la usará para revisar el diseño del compañero/a.", "Pactar un senyal per al canvi de seients (per exemple, un picament de mans) i recordar que el revisor/a no toca el model.|Pactar una señal para el cambio de asientos (por ejemplo, una palmada) y recordar que el revisor/a no toca el modelo."] },
    plan: [
      { min: 5, t: 'La revisió de la Nuvi|La revisión de Nuvi', fase: 'inici', fa: "Fes les preguntes de repàs (peces que floten, dues estrelles i un desig) i presenta la sessió: abans de la fira, cada disseny ha de passar la revisió de la Nuvi i la d'un company/a.|Haz las preguntas de repaso (piezas que flotan, dos estrellas y un deseo) y presenta la sesión: antes de la feria, cada diseño tiene que pasar la revisión de Nuvi y la de un compañero/a.",
        diu: ['Com sabem si un disseny es pot imprimir abans de gastar plàstic?|¿Cómo sabemos si un diseño se puede imprimir antes de gastar plástico?'], slides: ['s1', 's2'], app: 'Encara no: pantalles abaixades.|Todavía no: pantallas bajadas.', org: 'Tot el grup|Todo el grupo' },
      { min: 10, t: 'Les quatre proves i la rúbrica|Las cuatro pruebas y la rúbrica', fase: 'teoria', fa: "Explica les quatre proves de la Nuvi, per què tocar no és prou (fica-les 1-2 mm a dins) i per què les parets primes i les puntes es trenquen (gira els dos gots tallats). Acaba amb la rúbrica de la revisió per parelles i un exemple de bona nota.|Explica las cuatro pruebas de Nuvi, por qué tocar no basta (mételas 1-2 mm dentro) y por qué las paredes finas y las puntas se rompen (gira los dos vasos cortados). Acaba con la rúbrica de la revisión por parejas y un ejemplo de buena nota.",
        diu: ["Quin dels dos gots es trencaria abans? Per què?|¿Cuál de los dos vasos se rompería antes? ¿Por qué?", "Com diríeu aquest desig perquè ajudi i no faci mal?|¿Cómo diríais este deseo para que ayude y no haga daño?"], slides: ['s3', 's4', 's5', 's6'], app: "Encara no: tota l'atenció a la projecció.|Todavía no: toda la atención en la proyección.", org: 'Tot el grup|Todo el grupo' },
      { min: 15, t: "A l'ordinador: revisem dissenys|En el ordenador: revisamos diseños", fase: 'ordinador', fa: "Fan la sessió a l'app: la nota que ajuda més, el porta-pinzells de paret prima, el ninot amb el barret que flota i les tres revisions (paret d'1 a 2 mm, el cotxe que flota i l'ala que no toca). El coet és opcional.|Hacen la sesión en la app: la nota que ayuda más, el portapinceles de pared fina, el muñeco con el sombrero que flota y las tres revisiones (pared de 1 a 2 mm, el coche que flota y el ala que no toca). El cohete es opcional.",
        diu: ['Quina de les quatre proves falla en aquest model?|¿Cuál de las cuatro pruebas falla en este modelo?', 'Quants mil·límetres has de moure la peça perquè es fiqui a dins?|¿Cuántos milímetros tienes que mover la pieza para que se meta dentro?'], slides: ['s7', 's8', 's9'], app: "Sessió «Revisar-lo», fins a «La revisió per parelles».|Sesión «Revisarlo», hasta «La revisión por parejas».", org: 'Individual|Individual' },
      { min: 10, t: 'La versió 3|La versión 3', fase: 'crea', fa: "Cada alumne/a obre el seu disseny (pas «La versió 3: revisada») i el revisa amb les quatre proves fins que totes es marquen. No el desa encara: el deixa a la pantalla per a la revisió per parelles.|Cada alumno/a abre su diseño (paso «La versión 3: revisada») y lo revisa con las cuatro pruebas hasta que todas se marcan. No lo guarda todavía: lo deja en la pantalla para la revisión por parejas.",
        diu: ['Quina prova et falta? Què li passa al teu model?|¿Qué prueba te falta? ¿Qué le pasa a tu modelo?'], slides: ['s12'], app: "Pas «La versió 3: revisada» (sense desar encara).|Paso «La versión 3: revisada» (sin guardar todavía).", org: 'Individual|Individual' },
      { min: 14, t: 'La revisió per parelles|La revisión por parejas', fase: 'desconnectat', fa: "Al senyal, les parelles es canvien de seient. Cada revisor/a mira el disseny del company/a a la seva pantalla (gira, vistes i regle, sense tocar-lo) i omple la rúbrica en paper: quatre proves, encàrrec, dues estrelles i un desig. Tornen al seu lloc, llegeixen la rúbrica, apliquen el desig i desen la versió 3. Al final, cadascú apunta a l'app què li han dit.|A la señal, las parejas se cambian de asiento. Cada revisor/a mira el diseño del compañero/a en su pantalla (gira, vistas y regla, sin tocarlo) y rellena la rúbrica en papel: cuatro pruebas, encargo, dos estrellas y un deseo. Vuelven a su sitio, leen la rúbrica, aplican el deseo y guardan la versión 3. Al final, cada uno apunta en la app qué le han dicho.",
        diu: ["El teu desig té un número? Diu com millorar-ho?|¿Tu deseo tiene un número? ¿Dice cómo mejorarlo?", "Quin desig has decidit aplicar? Per què?|¿Qué deseo has decidido aplicar? ¿Por qué?"], slides: ['s10', 's11'], app: "Pas «La versió 3: revisada» i després «Què t'ha dit el teu revisor/a?».|Paso «La versión 3: revisada» y después «¿Qué te ha dicho tu revisor/a?».", org: 'Per parelles|Por parejas' },
      { min: 6, t: 'Tancament|Cierre', fase: 'tancament', fa: "Repassa les quatre proves i recull les rúbriques a la carpeta del projecte (serviran per a la presentació). Tiquet de sortida i proposta per a casa.|Repasa las cuatro pruebas y recoge las rúbricas en la carpeta del proyecto (servirán para la presentación). Ticket de salida y propuesta para casa.",
        diu: ["Quina millora has fet gràcies a la revisió?|¿Qué mejora has hecho gracias a la revisión?"], slides: ['s13', 's14', 's15'], app: "Les últimes preguntes i «Com t'ha anat?».|Las últimas preguntas y «¿Cómo te ha ido?».", org: 'Tot el grup|Todo el grupo' }
    ],
    errors: [["Al cotxe que flota, mou només una peça i la resta queda a l'aire.|En el coche que flota, mueve solo una pieza y el resto queda en el aire.", "Que torni a seleccionar totes les peces (botó «Totes») i escrigui z = 0 a Posició: baixen juntes.|Que vuelva a seleccionar todas las piezas (botón «Todas») y escriba z = 0 en Posición: bajan juntas."],
      ["Posa l'ala tocant el cos just a la vora i «És una sola peça» no es marca.|Pone el ala tocando el cuerpo justo en el borde y «Es una sola pieza» no se marca.", "Recorda-li la regla: fica-la 1 o 2 mm a dins. Amb y = −15, l'ala entra dins del cos.|Recuérdale la regla: métela 1 o 2 mm dentro. Con y = −15, el ala entra dentro del cuerpo."],
      ["Com a revisor/a, toca o canvia el model del company/a.|Como revisor/a, toca o cambia el modelo del compañero/a.", "Recorda que el revisor/a només mira i escriu: el disseny és de l'autor/a, i és ell o ella qui decideix què canvia.|Recuerda que el revisor/a solo mira y escribe: el diseño es del autor/a, y es él o ella quien decide qué cambia."],
      ["Escriu desitjos generals («millora-ho», «fes-lo més xulo»).|Escribe deseos generales («mejóralo», «hazlo más chulo»).", "Demana-li que miri la rúbrica i triï un criteri «a mig camí»: el desig ha de dir què canviar i, si pot, quant (mm).|Pídele que mire la rúbrica y elija un criterio «a medio camino»: el deseo tiene que decir qué cambiar y, si puede, cuánto (mm)."]],
    diff: { mes: "Fer el repte opcional del coet i, a la revisió, afegir un tercer criteri a la rúbrica pensat per a l'encàrrec del company/a (per exemple, «hi caben tres llapis»).|Hacer el reto opcional del cohete y, en la revisión, añadir un tercer criterio a la rúbrica pensado para el encargo del compañero/a (por ejemplo, «caben tres lápices»).",
      menys: "Revisar només amb les quatre proves (sense l'encàrrec) i escriure el desig amb la frase d'inici de la rúbrica. A l'app, fer les revisions amb la pista.|Revisar solo con las cuatro pruebas (sin el encargo) y escribir el deseo con la frase de inicio de la rúbrica. En la app, hacer las revisiones con la pista." },
    aval: { ticket: ['Digues les quatre proves de la Nuvi.|Di las cuatro pruebas de Nuvi.', "Digues un desig que has escrit al company/a.|Di un deseo que has escrito al compañero/a."],
      rubric: [['Les quatre proves|Las cuatro pruebas', "Revisa i arregla les quatre proves en models propis i aliens.|Revisa y arregla las cuatro pruebas en modelos propios y ajenos.", "Arregla alguna prova amb ajuda, però no sap explicar què fallava.|Arregla alguna prueba con ayuda, pero no sabe explicar qué fallaba."],
        ['La revisió al company/a|La revisión al compañero/a', "Omple la rúbrica i escriu dues estrelles i un desig concret i amable.|Rellena la rúbrica y escribe dos estrellas y un deseo concreto y amable.", "Escriu opinions generals que no ajuden a millorar.|Escribe opiniones generales que no ayudan a mejorar."],
        ['La versió 3|La versión 3', "Aplica almenys un desig i desa un disseny que passa les quatre proves.|Aplica al menos un deseo y guarda un diseño que pasa las cuatro pruebas.", "Desa el disseny, però sense aplicar cap millora de la revisió.|Guarda el diseño, pero sin aplicar ninguna mejora de la revisión."]] },
    casa: "Mira un objecte de plàstic de casa (una joguina, un tap, una pinça) i fes-li les quatre proves: té base plana? és una sola peça? hi ha parts massa primes? Explica-ho a algú de casa.|Mira un objeto de plástico de casa (un juguete, un tapón, una pinza) y hazle las cuatro pruebas: ¿tiene base plana? ¿es una sola pieza? ¿hay partes demasiado finas? Explícalo a alguien de casa.",
    intro: "Sessió de revisió: l'alumnat aprèn a mirar un disseny com un enginyer/a abans de fabricar-lo. Primer revisa i arregla models d'altres participants de la fira (paret prima, peces que floten o que només es toquen) i després fa el mateix amb el seu i el d'un company/a, amb una rúbrica. La retroacció es converteix en la versió 3.|Sesión de revisión: el alumnado aprende a mirar un diseño como un ingeniero/a antes de fabricarlo. Primero revisa y arregla modelos de otros participantes de la feria (pared fina, piezas que flotan o que solo se tocan) y después hace lo mismo con el suyo y el de un compañero/a, con una rúbrica. La retroalimentación se convierte en la versión 3.",
    claus: ["Les quatre proves: toca la placa, una sola peça, parets de 2 mm o més i cap a la placa.|Las cuatro pruebas: toca la placa, una sola pieza, paredes de 2 mm o más y cabe en la placa.", "Tocar no és prou: les peces es fiquen 1 o 2 mm l'una dins de l'altra.|Tocar no basta: las piezas se meten 1 o 2 mm una dentro de la otra.",
      "Les parets primes i les puntes es trenquen i punxen: millor 2 mm o més i puntes rodones.|Las paredes finas y las puntas se rompen y pinchan: mejor 2 mm o más y puntas redondas.", "Una bona revisió segueix la rúbrica i dona dues estrelles i un desig concret.|Una buena revisión sigue la rúbrica y da dos estrellas y un deseo concreto."],
    prev: ["Haver desat la versió 2 a la sessió «Modelar-lo».|Haber guardado la versión 2 en la sesión «Modelarlo».", "Conèixer els requisits d'impressió de la unitat 6 (base plana, res a l'aire, parets de 2 mm).|Conocer los requisitos de impresión de la unidad 6 (base plana, nada en el aire, paredes de 2 mm).", "Haver fet «dues estrelles i un desig» a la unitat 7.|Haber hecho «dos estrellas y un deseo» en la unidad 7."],
    faq: [["Per què la comprovació de parets no veu que el con punxa?|¿Por qué la comprobación de paredes no ve que el cono pincha?", "La comprovació mira sobretot les parets, i una punta és una part molt petita del model. Per això ensenyem les puntes com una qüestió de seguretat i qualitat i en fem un repte a part.|La comprobación mira sobre todo las paredes, y una punta es una parte muy pequeña del modelo. Por eso enseñamos las puntas como una cuestión de seguridad y calidad y hacemos un reto aparte."],
      ["Un alumne/a no aconsegueix que el seu disseny passi les quatre proves. Què fem?|Un alumno/a no consigue que su diseño pase las cuatro pruebas. ¿Qué hacemos?", "Mireu quina prova falla i amb quina peça: amb «Resultat» i les vistes se sol veure de seguida. Si hi ha estrelles o formes molt primes, proveu de fer-les més gruixudes o de canviar-les per una forma rodona.|Mirad qué prueba falla y con qué pieza: con «Resultado» y las vistas se suele ver enseguida. Si hay estrellas o formas muy finas, probad a hacerlas más gruesas o a cambiarlas por una forma redonda."],
      ["On queda guardada la revisió que fan a l'app?|¿Dónde queda guardada la revisión que hacen en la app?", "Al perfil de cada alumne/a. Les rúbriques de paper són les que fan servir per presentar: guardeu-les a la carpeta del projecte.|En el perfil de cada alumno/a. Las rúbricas de papel son las que usan para presentar: guardadlas en la carpeta del proyecto."]],
    tec: [["El botó «Desa-ho i continua» de la versió 3 no s'activa.|El botón «Guárdalo y continúa» de la versión 3 no se activa.", "Només s'activa quan es marquen les quatre proves. Mireu quina falta i amb quina peça: és la feina de la sessió.|Solo se activa cuando se marcan las cuatro pruebas. Mirad cuál falta y con qué pieza: es el trabajo de la sesión."],
      ["La versió 3 comença amb el test de la Jana amb l'etiqueta separada.|La versión 3 empieza con la maceta de Jana con la etiqueta separada.", "Vol dir que no hi ha cap versió 2 desada. L'alumne/a pot revisar el test de la Jana (enganxant l'etiqueta) o refer el seu disseny a partir de la fitxa.|Quiere decir que no hay ninguna versión 2 guardada. El alumno/a puede revisar la maceta de Jana (pegando la etiqueta) o rehacer su diseño a partir de la ficha."],
      ["Al canvi de seients, el revisor/a ha mogut el model sense voler.|En el cambio de asientos, el revisor/a ha movido el modelo sin querer.", "L'autor/a pot fer servir el botó de desfer (la fletxa enrere) per tornar-lo a deixar com estava.|El autor/a puede usar el botón de deshacer (la flecha hacia atrás) para volver a dejarlo como estaba."]],
    extra: ["Fer un «taller de reparació»: cada alumne/a desa un model amb un error a propòsit i un company/a l'ha de trobar i arreglar.|Hacer un «taller de reparación»: cada alumno/a guarda un modelo con un error a propósito y un compañero/a lo tiene que encontrar y arreglar.", "Escriure entre tots una llista de «frases que ajuden» per a les revisions i penjar-la a l'aula.|Escribir entre todos una lista de «frases que ayudan» para las revisiones y colgarla en el aula.", "Si teniu impressora, imprimir el porta-pinzells d'en Biel amb parets d'1 i de 2 mm i comparar-ne la força (amb cura).|Si tenéis impresora, imprimir el portapinceles de Biel con paredes de 1 y de 2 mm y comparar su fuerza (con cuidado)."],
    trans: ["Sessió següent: la presentació a la Fira d'Invents, l'STL i el diploma.|Sesión siguiente: la presentación en la Feria de Inventos, el STL y el diploma.", "Valors: donar i rebre retroacció amb respecte.|Valores: dar y recibir retroalimentación con respeto."],
    slides: [
      { id: 's1', k: 'portada', t: 'Revisar-lo|Revisarlo', x: 'Les quatre proves de la Nuvi i la revisió per parelles|Las cuatro pruebas de Nuvi y la revisión por parejas', nota: "Parada 3 del projecte: avui el disseny es deixa a punt per imprimir.|Parada 3 del proyecto: hoy el diseño se deja a punto para imprimir." },
      { id: 's2', k: 'pregunta', t: 'Es pot imprimir?|¿Se puede imprimir?', x: 'Com ho sabem abans de gastar plàstic i temps?|¿Cómo lo sabemos antes de gastar plástico y tiempo?', nota: "Recull respostes: busquem que recordin la base plana, res a l'aire i les parets de 2 mm.|Recoge respuestas: buscamos que recuerden la base plana, nada en el aire y las paredes de 2 mm." },
      { id: 's3', k: 'anim', t: 'Les quatre proves|Las cuatro pruebas', anim: 'm8proves', x: 'Toca la placa · una sola peça · parets de 2 mm · cap a la placa|Toca la placa · una sola pieza · paredes de 2 mm · cabe en la placa', nota: "Relaciona cada prova amb la comprovació de l'app que la revisa.|Relaciona cada prueba con la comprobación de la app que la revisa." },
      { id: 's4', k: 'anim', t: 'Tocar no és prou|Tocar no basta', anim: 'm8toca', x: 'Fica-la 1 o 2 mm a dins.|Métela 1 o 2 mm dentro.', nota: "Fes-ho amb dues peces de plastilina: tocant-se només, se separen; ficades, s'aguanten.|Hazlo con dos piezas de plastilina: solo tocándose, se separan; metidas, se aguantan." },
      { id: 's5', k: 'media', t: 'Parets primes|Paredes finas', x: "Paret d'1 mm (blau) i paret de 2 mm (verd), tallats pel mig.|Pared de 1 mm (azul) y pared de 2 mm (verde), cortados por la mitad.", media: { k: 'model', model: PRIMS, view: 'front', spin: false }, nota: "Pregunta quin es trencaria abans i quantes línies del broquet caben en cada paret.|Pregunta cuál se rompería antes y cuántas líneas de la boquilla caben en cada pared." },
      { id: 's6', k: 'anim', t: 'La revisió per parelles|La revisión por parejas', anim: 'm8rubrica', x: 'Rúbrica · dues estrelles · un desig concret|Rúbrica · dos estrellas · un deseo concreto', nota: "Llegiu junts la rúbrica de paper i feu entre tots un desig de mostra.|Leed juntos la rúbrica de papel y haced entre todos un deseo de muestra." },
      { id: 's7', k: 'media', t: "El porta-pinzells d'en Biel|El portapinceles de Biel", x: 'Paret de (40 − 38) ÷ 2 = 1 mm: massa prima.|Pared de (40 − 38) ÷ 2 = 1 mm: demasiado fina.', media: { k: 'model', model: BIEL, spin: false }, nota: "Tallat pel mig es veu la paret prima. Amb un forat de 36 mm, farà 2 mm.|Cortado por la mitad se ve la pared fina. Con un agujero de 36 mm, medirá 2 mm." },
      { id: 's8', k: 'media', t: 'El ninot de la Carla|El muñeco de Carla', x: 'El barret flota 3 mm: la Nuvi l\'imprimiria a l\'aire.|El sombrero flota 3 mm: Nuvi lo imprimiría en el aire.', media: { k: 'model', model: NINOT, view: 'front' }, nota: "Pregunta quants mil·límetres cal baixar-lo perquè es fiqui 1 mm al cap (4 mm).|Pregunta cuántos milímetros hay que bajarlo para que se meta 1 mm en la cabeza (4 mm)." },
      { id: 's9', k: 'repte', t: "A l'ordinador: revisions|En el ordenador: revisiones", punts: ["Biel: forat de 36 mm (paret de 2 mm).|Biel: agujero de 36 mm (pared de 2 mm).", "Ona: tot el cotxe a z = 0.|Ona: todo el coche en z = 0.", "Pia: l'ala a y = −15.|Pia: el ala en y = −15."], nota: "Abans d'arreglar, que diguin quina de les quatre proves falla.|Antes de arreglar, que digan cuál de las cuatro pruebas falla." },
      { id: 's10', k: 'concepte', t: 'Normes de la revisió|Normas de la revisión', x: "El revisor/a mira i escriu, però no toca el model. Parla del disseny, no de la persona. L'autor/a decideix què canvia.|El revisor/a mira y escribe, pero no toca el modelo. Habla del diseño, no de la persona. El autor/a decide qué cambia.", nota: "Llegiu-les abans del canvi de seients i acordeu el senyal.|Leedlas antes del cambio de asientos y acordad la señal." },
      { id: 's11', k: 'activitat', t: 'La revisió per parelles|La revisión por parejas', timer: 10, punts: ["Canvi de seient: mira el disseny del company/a.|Cambio de asiento: mira el diseño del compañero/a.", 'Omple la rúbrica.|Rellena la rúbrica.', 'Dues estrelles i un desig.|Dos estrellas y un deseo.', 'Torna, llegeix i millora.|Vuelve, lee y mejora.'], nota: "Uns 5 minuts de revisió i 5 per tornar, llegir i aplicar el desig.|Unos 5 minutos de revisión y 5 para volver, leer y aplicar el deseo." },
      { id: 's12', k: 'repte', t: 'La versió 3: revisada|La versión 3: revisada', punts: ['Que passi les quatre proves.|Que pase las cuatro pruebas.', "Deixa-la a la pantalla per a la revisió.|Déjala en la pantalla para la revisión.", 'Aplica el desig i desa-la.|Aplica el deseo y guárdala.'], nota: "Ajuda primer els qui encara no passen alguna prova.|Ayuda primero a quien todavía no pasa alguna prueba." },
      { id: 's13', k: 'resum', t: 'Avui hem après…|Hoy hemos aprendido…', punts: ['Les quatre proves de la Nuvi.|Las cuatro pruebas de Nuvi.', 'Fica les peces 1 o 2 mm a dins.|Mete las piezas 1 o 2 mm dentro.', 'Revisar amb una rúbrica, amb amabilitat.|Revisar con una rúbrica, con amabilidad.'], nota: 'Llegiu-ho junts.|Leedlo juntos.' },
      { id: 's14', k: 'tiquet', t: 'Tiquet de sortida|Ticket de salida', punts: ['Les quatre proves.|Las cuatro pruebas.', 'Un desig que has escrit.|Un deseo que has escrito.'], nota: 'Oral, abans de sortir.|Oral, antes de salir.' },
      { id: 's15', k: 'concepte', t: 'A casa|En casa', x: "Fes les quatre proves a un objecte de plàstic de casa i explica-ho a algú.|Haz las cuatro pruebas a un objeto de plástico de casa y explícalo a alguien.", nota: 'Proposta opcional.|Propuesta opcional.' }
    ],
    print: [{ id: 'p1', t: 'Rúbrica de revisió per parelles|Rúbrica de revisión por parejas', k: 'fitxa', intro: "Mira el disseny del teu company/a a la seva pantalla, sense tocar-lo. Per a cada criteri, marca ✓ (aconseguit), ~ (a mig camí) o … (encara no).|Mira el diseño de tu compañero/a en su pantalla, sin tocarlo. Para cada criterio, marca ✓ (conseguido), ~ (a medio camino) o … (todavía no).",
      items: [{ q: 'Disseny de: ____ · Per a qui és: ____|Diseño de: ____ · Para quién es: ____', sol: 'Resposta oberta.|Respuesta abierta.' },
        { q: 'Toca la placa ____ · Una sola peça ____ · Parets de 2 mm o més ____ · Cap a la placa ____|Toca la placa ____ · Una sola pieza ____ · Paredes de 2 mm o más ____ · Cabe en la placa ____', sol: "Les quatre proves es poden comprovar amb les marques de l'app i les vistes.|Las cuatro pruebas se pueden comprobar con las marcas de la app y las vistas." },
        { q: "Respon a l'encàrrec (fa el que diu la fitxa)? ____|¿Responde al encargo (hace lo que dice la ficha)? ____", sol: "Mireu la fitxa de l'autor/a: per a qui és i els requisits.|Mirad la ficha del autor/a: para quién es y los requisitos." },
        { q: '⭐ ⭐ Dues coses que funcionen bé: ____|⭐ ⭐ Dos cosas que funcionan bien: ____', sol: 'Qualitats concretes (la base és ampla, les nanses són simètriques…).|Cualidades concretas (la base es ancha, las asas son simétricas…).' },
        { q: "💬 Un desig: «Podries… (amb números si pots)» ____|💬 Un deseo: «Podrías… (con números si puedes)» ____", sol: "Per exemple: «Podries fer la paret de 2 mm en lloc d'1».|Por ejemplo: «Podrías hacer la pared de 2 mm en lugar de 1»." }] }]
  },
  /* ---------- Sessió 4 · Presentació i diploma ---------- */
  'm8-4': {
    obj: ["L'alumne/a presenta el seu disseny: què és, per a qui, la millor vista, les mides, com l'ha fet i què ha millorat.|El alumno/a presenta su diseño: qué es, para quién, la mejor vista, las medidas, cómo lo ha hecho y qué ha mejorado.",
      "L'alumne/a exporta el seu disseny en STL a mida real i explica el camí fins a la impressora.|El alumno/a exporta su diseño en STL a tamaño real y explica el camino hasta la impresora.",
      "L'alumne/a repassa els conceptes clau del curs (vistes, mesures, capes, marge i forats) en reptes curts.|El alumno/a repasa los conceptos clave del curso (vistas, medidas, capas, margen y agujeros) en retos cortos.",
      "L'alumne/a valora el seu procés de disseny i rep el diploma del curs.|El alumno/a valora su proceso de diseño y recibe el diploma del curso."],
    comp: ["Tecnologia i digitalització: comunicar un projecte tecnològic i preparar-lo per a la fabricació digital|Tecnología y digitalización: comunicar un proyecto tecnológico y prepararlo para la fabricación digital",
      "Comunicació oral: presentar en públic amb un guió i respondre preguntes|Comunicación oral: presentar en público con un guion y responder preguntas",
      "Matemàtiques, sentit de la mesura i espacial: mides, vistes i capes|Matemáticas, sentido de la medida y espacial: medidas, vistas y capas",
      "Competència personal i d'aprendre a aprendre: reflexionar sobre el propi aprenentatge|Competencia personal y de aprender a aprender: reflexionar sobre el propio aprendizaje"],
    vocab: [['Presentació|Presentación', "Explicar en públic el disseny, amb un guió curt i ensenyant el model.|Explicar en público el diseño, con un guion corto y enseñando el modelo."],
      ['Fitxa del producte|Ficha del producto', "Nom, per a qui és, què fa, mides i material d'un objecte.|Nombre, para quién es, qué hace, medidas y material de un objeto."],
      ['STL|STL', "Fitxer que descriu la forma del model amb triangles, a mida real en mm.|Archivo que describe la forma del modelo con triángulos, a tamaño real en mm."],
      ['Laminador|Laminador', "Programa que talla el model en capes i prepara el camí del broquet.|Programa que corta el modelo en capas y prepara el camino de la boquilla."],
      ['Estand|Estand', "El lloc de la fira on cada inventor/a ensenya el seu disseny.|El sitio de la feria donde cada inventor/a enseña su diseño."],
      ['Diploma|Diploma', "Document que reconeix que has acabat el curs i el que has après.|Documento que reconoce que has terminado el curso y lo que has aprendido."]],
    mat: { aula: ["Un ordinador per alumne/a amb Numi Tech obert a la sessió «Presentació i diploma»|Un ordenador por alumno/a con Numi Tech abierto en la sesión «Presentación y diploma»", 'Projector i la presentació de la sessió|Proyector y la presentación de la sesión',
      "La fitxa del projecte, la rúbrica de la revisió i el guió de la presentació|La ficha del proyecto, la rúbrica de la revisión y el guion de la presentación", 'Els diplomes impresos, un per alumne/a|Los diplomas impresos, uno por alumno/a'],
      imprimir: ['Guió de la presentació i fitxa del producte|Guion de la presentación y ficha del producto', 'Diploma del curs|Diploma del curso'],
      prep: ["Imprimir el guió i un diploma per alumne/a. Escriure-hi el nom abans de la classe i signar-los.|Imprimir el guion y un diploma por alumno/a. Escribir el nombre antes de la clase y firmarlos.", "Organitzar l'ordre de les presentacions: uns quants al projector i la resta per grups o en una galeria d'estands.|Organizar el orden de las presentaciones: unos cuantos en el proyector y el resto por grupos o en una galería de estands.",
        "Si teniu impressora, imprimir abans alguns dissenys de la versió 3 per ensenyar-los a la fira. Si no, l'STL es pot imprimir més endavant.|Si tenéis impresora, imprimir antes algunos diseños de la versión 3 para enseñarlos en la feria. Si no, el STL se puede imprimir más adelante.", "Si es vol, convidar les famílies o una altra classe als darrers 20 minuts.|Si se quiere, invitar a las familias o a otra clase a los últimos 20 minutos."] },
    plan: [
      { min: 4, t: "S'obre la fira!|¡Se abre la feria!", fase: 'inici', fa: "Dona la benvinguda a l'última sessió: avui és la Fira d'Invents. Fes la pregunta de repàs sobre les quatre proves i explica l'ordre: preparar, reptes de la fira, presentacions i diplomes.|Da la bienvenida a la última sesión: hoy es la Feria de Inventos. Haz la pregunta de repaso sobre las cuatro pruebas y explica el orden: preparar, retos de la feria, presentaciones y diplomas.",
        diu: ['Quines quatre proves ha passat el vostre disseny?|¿Qué cuatro pruebas ha pasado vuestro diseño?'], slides: ['s1', 's2'], app: 'Encara no: pantalles abaixades.|Todavía no: pantallas bajadas.', org: 'Tot el grup|Todo el grupo' },
      { min: 8, t: 'Presentar un disseny|Presentar un diseño', fase: 'teoria', fa: "Repassa el viatge de les vuit unitats, mostra la fitxa del producte de la Jana i explica les quatre parts de la presentació. Acaba amb el camí de l'STL fins a la impressora.|Repasa el viaje de las ocho unidades, muestra la ficha del producto de Jana y explica las cuatro partes de la presentación. Acaba con el camino del STL hasta la impresora.",
        diu: ["Quina vista triaríeu per ensenyar el vostre invent? Per què?|¿Qué vista elegiríais para enseñar vuestro invento? ¿Por qué?", "Què li passa al fitxer STL des que el descarreguem fins que la Nuvi acaba?|¿Qué le pasa al archivo STL desde que lo descargamos hasta que Nuvi acaba?"], slides: ['s3', 's4', 's5', 's6'], app: "Encara no: tota l'atenció a la projecció.|Todavía no: toda la atención en la proyección.", org: 'Tot el grup|Todo el grupo' },
      { min: 6, t: 'El guió|El guion', fase: 'desconnectat', fa: "Cada alumne/a omple el guió de la presentació i la fitxa del producte (nom, per a qui, què fa, mides, material i què ha millorat), amb la fitxa del projecte i la rúbrica de la revisió a la vista.|Cada alumno/a rellena el guion de la presentación y la ficha del producto (nombre, para quién, qué hace, medidas, material y qué ha mejorado), con la ficha del proyecto y la rúbrica de la revisión a la vista.",
        diu: ["Quina millora explicaràs? D'on va sortir?|¿Qué mejora explicarás? ¿De dónde salió?"], slides: ['s7'], app: 'Encara no: el guió.|Todavía no: el guion.', org: 'Individual|Individual' },
      { min: 14, t: "A l'ordinador: repàs i reptes de la fira|En el ordenador: repaso y retos de la feria", fase: 'ordinador', fa: "Fan la sessió a l'app: ordenar la presentació, el repàs del curs (z de la base, capes i vistes) i els dos reptes de la fira (el porta-targetes amb marge i el trofeu).|Hacen la sesión en la app: ordenar la presentación, el repaso del curso (z de la base, capas y vistas) y los dos retos de la feria (el portatarjetas con margen y el trofeo).",
        diu: ['Per què la ranura fa 56 × 3 mm si la targeta fa 54 × 1?|¿Por qué la ranura mide 56 × 3 mm si la tarjeta mide 54 × 1?', 'Per què la bola es fica 4 mm a la columna?|¿Por qué la bola se mete 4 mm en la columna?'], slides: ['s8', 's9', 's10'], app: "Sessió «Presentació i diploma», fins a «Assaja la presentació».|Sesión «Presentación y diploma», hasta «Ensaya la presentación».", org: 'Individual|Individual' },
      { min: 20, t: "La Fira d'Invents|La Feria de Inventos", fase: 'crea', fa: "Per parelles assagen la presentació un minut. Després, al pas «La versió final», cada alumne/a dona l'últim retoc, descarrega l'STL i presenta: alguns al projector i la resta per grups (o en una galeria d'estands amb les fitxes del producte). En acabar la presentació, desa el disseny final.|Por parejas ensayan la presentación un minuto. Después, en el paso «La versión final», cada alumno/a da el último retoque, descarga el STL y presenta: algunos en el proyector y el resto por grupos (o en una galería de estands con las fichas del producto). Al acabar la presentación, guarda el diseño final.",
        diu: ['Per a qui és el teu invent? Quines mides té?|¿Para quién es tu invento? ¿Qué medidas tiene?', 'Què hi afegiríeu, vosaltres, al disseny del company/a?|¿Qué le añadiríais vosotros al diseño del compañero/a?'], slides: ['s11', 's12'], app: "Passos «Assaja la presentació» i «La versió final».|Pasos «Ensaya la presentación» y «La versión final».", org: 'Per parelles i tot el grup|Por parejas y todo el grupo' },
      { min: 8, t: 'Diplomes i tancament|Diplomas y cierre', fase: 'tancament', fa: "Cada alumne/a arriba al pas del diploma a l'app i, mentrestant, lliura el diploma imprès a cadascú amb un aplaudiment. Acaba amb el missatge d'en Bit, l'última pregunta, el tiquet de sortida i un comiat.|Cada alumno/a llega al paso del diploma en la app y, mientras tanto, entrega el diploma impreso a cada uno con un aplauso. Acaba con el mensaje de Bit, la última pregunta, el ticket de salida y una despedida.",
        diu: ["Què és el que més t'ha agradat aprendre al curs?|¿Qué es lo que más te ha gustado aprender en el curso?", 'Quin seria el teu proper invent?|¿Cuál sería tu próximo invento?'], slides: ['s13', 's14', 's15', 's16'], app: "«Tancament»: el diploma de l'app (es pot imprimir), el missatge d'en Bit, la pregunta final i com m'he sentit.|«Cierre»: el diploma de la app (se puede imprimir), el mensaje de Bit, la pregunta final y cómo me he sentido.", org: 'Tot el grup|Todo el grupo' }
    ],
    errors: [["A la presentació, llegeix el guió sencer mirant el paper o la pantalla.|En la presentación, lee el guion entero mirando el papel o la pantalla.", "Que faci servir el guió només com a recordatori (una paraula per part) i que miri el públic mentre gira el model.|Que use el guion solo como recordatorio (una palabra por parte) y que mire al público mientras gira el modelo."],
      ["No sap dir les mides del seu disseny.|No sabe decir las medidas de su diseño.", "Al pas de la versió final, que toqui «Totes» i miri la pestanya Mida: veurà l'amplada, la fondària i l'alçada de tot el model.|En el paso de la versión final, que toque «Todas» y mire la pestaña Medida: verá la anchura, el fondo y la altura de todo el modelo."],
      ["Al porta-targetes, fa la ranura de 54 × 1 mm, igual que la targeta.|En el portatarjetas, hace la ranura de 54 × 1 mm, igual que la tarjeta.", "Recorda-li el marge de la unitat 7: el forat ha de ser una mica més gran que el que hi entra (+2 mm).|Recuérdale el margen de la unidad 7: el agujero tiene que ser un poco más grande que lo que entra (+2 mm)."],
      ["Desa el disseny final sense haver descarregat l'STL.|Guarda el diseño final sin haber descargado el STL.", "Pot descarregar-lo igualment des de «Projectes»: cada projecte desat té el botó STL.|Puede descargarlo igualmente desde «Proyectos»: cada proyecto guardado tiene el botón STL."]],
    diff: { mes: "Preparar una presentació amb una demostració (girar el model, mostrar el tall amb «Resultat», comparar la v1 i la v3 a «Projectes») i respondre dues preguntes del públic.|Preparar una presentación con una demostración (girar el modelo, mostrar el corte con «Resultado», comparar la v1 y la v3 en «Proyectos») y responder dos preguntas del público.",
      menys: "Presentar en un grup petit amb el guió de frases d'inici i només tres parts: què és, per a qui i què ha millorat.|Presentar en un grupo pequeño con el guion de frases de inicio y solo tres partes: qué es, para quién y qué ha mejorado." },
    aval: { ticket: ['Digues tres coses que has après en aquest curs.|Di tres cosas que has aprendido en este curso.', "Digues quin seria el teu proper invent.|Di cuál sería tu próximo invento."],
      rubric: [['La presentació|La presentación', "Explica què és, per a qui, les mides, com l'ha fet i què ha millorat, mirant el públic.|Explica qué es, para quién, las medidas, cómo lo ha hecho y qué ha mejorado, mirando al público.", "Ensenya el model però en diu poca cosa o només en llegeix el guió.|Enseña el modelo pero dice poca cosa o solo lee el guion."],
        ['El disseny final|El diseño final', "Respon a l'encàrrec, passa les proves d'impressió i se n'ha descarregat l'STL.|Responde al encargo, pasa las pruebas de impresión y se ha descargado su STL.", "El disseny està acabat, però no respon a l'encàrrec o falta l'STL.|El diseño está acabado, pero no responde al encargo o falta el STL."],
        ['El procés|El proceso', "Pot explicar el camí sencer: encàrrec, esbós, model, revisió i millora.|Puede explicar el camino entero: encargo, boceto, modelo, revisión y mejora.", "Recorda alguna fase, però no les relaciona entre elles.|Recuerda alguna fase, pero no las relaciona entre ellas."]] },
    casa: "Ensenya el teu disseny a casa des de «Projectes»: gira'l, explica'n les mides i per a qui és. Si teniu accés a una impressora 3D (a la biblioteca, a un centre cívic o a un taller de fabricació), podeu imprimir-ne l'STL.|Enseña tu diseño en casa desde «Proyectos»: gíralo, explica sus medidas y para quién es. Si tenéis acceso a una impresora 3D (en la biblioteca, en un centro cívico o en un taller de fabricación), podéis imprimir su STL.",
    intro: "Última sessió del curs: la Fira d'Invents. L'alumnat repassa el viatge de les vuit unitats, prepara un guió de quatre parts, resol dos reptes curts que combinen eines del curs, descarrega l'STL del seu disseny final i el presenta. La sessió acaba amb el diploma, a l'app i en paper.|Última sesión del curso: la Feria de Inventos. El alumnado repasa el viaje de las ocho unidades, prepara un guion de cuatro partes, resuelve dos retos cortos que combinan herramientas del curso, descarga el STL de su diseño final y lo presenta. La sesión acaba con el diploma, en la app y en papel.",
    claus: ["Una presentació clara té quatre parts: què és i per a qui, vista i mides, com s'ha fet i què s'ha millorat.|Una presentación clara tiene cuatro partes: qué es y para quién, vista y medidas, cómo se ha hecho y qué se ha mejorado.", "L'STL és el fitxer que va a la impressora, a mida real i en mil·límetres.|El STL es el archivo que va a la impresora, a tamaño real y en milímetros.",
      "El camí del disseny és un cercle: escoltar, esbossar, modelar, revisar i millorar.|El camino del diseño es un círculo: escuchar, esbozar, modelar, revisar y mejorar.", "Celebrar la feina feta també és part del projecte.|Celebrar el trabajo hecho también es parte del proyecto."],
    prev: ["Haver desat la versió 3 a la sessió «Revisar-lo» (o, si no, una versió anterior).|Haber guardado la versión 3 en la sesión «Revisarlo» (o, si no, una versión anterior).", "Tenir la fitxa del projecte i la rúbrica de la revisió.|Tener la ficha del proyecto y la rúbrica de la revisión.", "Saber descarregar un STL (unitat 6).|Saber descargar un STL (unidad 6)."],
    faq: [["El diploma de l'app és el mateix que el de paper?|¿El diploma de la app es el mismo que el de papel?", "Tots dos diuen què s'ha après durant el curs. El de l'app es pot imprimir a casa; el de paper el lliura el professor/a.|Los dos dicen qué se ha aprendido durante el curso. El de la app se puede imprimir en casa; el de papel lo entrega el profesor/a."],
      ["No tenim impressora 3D. Té sentit la fira?|No tenemos impresora 3D. ¿Tiene sentido la feria?", "Sí: el disseny es presenta en 3D a la pantalla i l'STL queda a punt per imprimir-lo més endavant (en un centre cívic, una biblioteca o un altre centre). El que s'avalua és el procés i el disseny.|Sí: el diseño se presenta en 3D en la pantalla y el STL queda listo para imprimirlo más adelante (en un centro cívico, una biblioteca u otro centro). Lo que se evalúa es el proceso y el diseño."],
      ["No hi ha temps perquè tothom presenti al projector.|No hay tiempo para que todo el mundo presente en el proyector.", "Feu presentar tres o quatre alumnes al projector i la resta en grups de quatre, o bé una galeria d'estands: la meitat presenta i l'altra meitat visita, i després es canvien.|Haced presentar a tres o cuatro alumnos en el proyector y el resto en grupos de cuatro, o bien una galería de estands: la mitad presenta y la otra mitad visita, y después se cambian."]],
    tec: [["A la versió final, l'app no torna a exigir la prova de les parets.|En la versión final, la app no vuelve a exigir la prueba de las paredes.", "És a propòsit: les parets es van revisar a la sessió 3 i així ningú no es queda encallat abans del diploma. Si algun disseny encara té parts primes, comenteu-ho a la presentació com a millora per a la versió següent.|Es a propósito: las paredes se revisaron en la sesión 3 y así nadie se queda atascado antes del diploma. Si algún diseño todavía tiene partes finas, comentadlo en la presentación como mejora para la versión siguiente."],
      ["El pas del diploma no mostra totes les sessions fetes.|El paso del diploma no muestra todas las sesiones hechas.", "El diploma compta les sessions acabades en aquest perfil. Si l'alumne/a n'ha fet alguna en un altre dispositiu o perfil, no hi surt, però el diploma és vàlid igualment.|El diploma cuenta las sesiones acabadas en este perfil. Si el alumno/a ha hecho alguna en otro dispositivo o perfil, no sale, pero el diploma es válido igualmente."],
      ["El botó STL no descarrega res.|El botón STL no descarga nada.", "Comproveu que el navegador permet descàrregues. També es pot descarregar des de «Projectes», obrint el projecte desat.|Comprobad que el navegador permite descargas. También se puede descargar desde «Proyectos», abriendo el proyecto guardado."],
      ["El diploma imprès surt tallat.|El diploma impreso sale cortado.", "Imprimiu-lo des de «Fitxes per imprimir», en A4 i a escala del 100 %. A l'app, el botó «Imprimeix» del pas del diploma també funciona.|Imprimidlo desde «Fichas para imprimir», en A4 y a escala del 100 %. En la app, el botón «Imprimir» del paso del diploma también funciona."]],
    extra: ["Fer una exposició «Invents de la classe» amb les fitxes del producte i les miniatures (o les peces impreses) a l'entrada de l'escola.|Hacer una exposición «Inventos de la clase» con las fichas del producto y las miniaturas (o las piezas impresas) en la entrada de la escuela.", "Votar el premi a l'invent més útil, al més ben revisat i al que ha millorat més de la v1 a la v3.|Votar el premio al invento más útil, al mejor revisado y al que más ha mejorado de la v1 a la v3.", "Escriure una carta a la persona per a qui és l'invent explicant-li com funciona.|Escribir una carta a la persona para quien es el invento explicándole cómo funciona."],
    trans: ["Continuació: Tech 3D · Nivell 2, on es dissenya amb blocs i codi (paràmetres, operacions i patrons).|Continuación: Tech 3D · Nivel 2, donde se diseña con bloques y código (parámetros, operaciones y patrones).", "Tecnologia: el procés tecnològic complet, de la necessitat a la presentació del producte.|Tecnología: el proceso tecnológico completo, de la necesidad a la presentación del producto."],
    slides: [
      { id: 's1', k: 'portada', t: 'Presentació i diploma|Presentación y diploma', x: "S'obre la Fira d'Invents!|¡Se abre la Feria de Inventos!", nota: "Explica l'ordre de la sessió: preparar, reptes, presentacions i diplomes.|Explica el orden de la sesión: preparar, retos, presentaciones y diplomas." },
      { id: 's2', k: 'repas', t: 'Les quatre proves|Las cuatro pruebas', punts: ['Toca la placa|Toca la placa', 'Una sola peça|Una sola pieza', 'Parets de 2 mm o més|Paredes de 2 mm o más', 'Cap a la placa|Cabe en la placa'], nota: "Que aixequin la mà els qui les passen totes quatre.|Que levanten la mano quienes las pasan las cuatro." },
      { id: 's3', k: 'anim', t: 'El viatge del curs|El viaje del curso', anim: 'm8viatge', x: 'Vuit unitats, un dissenyador/a.|Ocho unidades, un diseñador/a.', nota: "Demana un record de cada unitat: què hi vam fer?|Pide un recuerdo de cada unidad: ¿qué hicimos?" },
      { id: 's4', k: 'media', t: 'La fitxa del producte|La ficha del producto', x: "Test de l'hort · per a P4 · 76 × 65 × 56 mm · PLA|Maceta del huerto · para P4 · 76 × 65 × 56 mm · PLA", media: { k: 'model', model: JANA }, nota: "Gira el test i mostra d'on surten les tres mides.|Gira la maceta y muestra de dónde salen las tres medidas." },
      { id: 's5', k: 'anim', t: 'Presentar en quatre parts|Presentar en cuatro partes', anim: 'm8pitch', x: "Què és · vista i mides · com l'he fet · què he millorat|Qué es · vista y medidas · cómo lo he hecho · qué he mejorado", nota: "Fes una presentació de mostra amb el test de la Jana, d'un minut.|Haz una presentación de muestra con la maceta de Jana, de un minuto." },
      { id: 's6', k: 'anim', t: 'De la pantalla a la Nuvi|De la pantalla a Nuvi', anim: 'm8stl', x: 'STL a mida real · laminador · capa a capa|STL a tamaño real · laminador · capa a capa', nota: "Recorda que l'STL no guarda els colors: sortirà del color del filament.|Recuerda que el STL no guarda los colores: saldrá del color del filamento." },
      { id: 's7', k: 'activitat', t: 'El guió|El guion', timer: 6, punts: ['Nom i per a qui.|Nombre y para quién.', 'Mides i material.|Medidas y material.', "Com l'he fet i què he millorat.|Cómo lo he hecho y qué he mejorado."], nota: "Que escriguin poques paraules per part: el guió és un recordatori.|Que escriban pocas palabras por parte: el guion es un recordatorio." },
      { id: 's8', k: 'repte', t: "A l'ordinador: repàs i reptes|En el ordenador: repaso y retos", punts: ['Ordena la presentació.|Ordena la presentación.', 'Repàs: z, capes i vistes.|Repaso: z, capas y vistas.', 'El porta-targetes i el trofeu.|El portatarjetas y el trofeo.'], nota: "Els reptes de la fira són curts: si algú acaba aviat, que polisca el seu guió.|Los retos de la feria son cortos: si alguien acaba pronto, que pula su guion." },
      { id: 's9', k: 'media', t: 'El porta-targetes|El portatarjetas', x: 'Targeta de 54 × 1 mm → ranura de 56 × 3 mm.|Tarjeta de 54 × 1 mm → ranura de 56 × 3 mm.', media: { k: 'model', model: PT, view: 'top' }, nota: "És el marge de la unitat 7: 2 mm més que el que hi entra.|Es el margen de la unidad 7: 2 mm más que lo que entra." },
      { id: 's10', k: 'media', t: 'El trofeu|El trofeo', x: "La bola es fica 4 mm a la columna: una sola peça.|La bola se mete 4 mm en la columna: una sola pieza.", media: { k: 'model', model: TROF }, nota: "Recorda que si només es toquessin podrien sortir separades.|Recuerda que si solo se tocaran podrían salir separadas." },
      { id: 's11', k: 'activitat', t: 'Assaja la presentació|Ensaya la presentación', timer: 4, punts: ['Un minut per persona.|Un minuto por persona.', 'Qui escolta regala una estrella.|Quien escucha regala una estrella.', 'I una pregunta.|Y una pregunta.'], nota: "Per parelles, amb el guió a la mà.|Por parejas, con el guion en la mano." },
      { id: 's12', k: 'activitat', t: "La Fira d'Invents|La Feria de Inventos", timer: 15, punts: ["Descarrega l'STL del teu disseny.|Descarga el STL de tu diseño.", 'Presenta en quatre parts.|Presenta en cuatro partes.', 'Desa la versió final.|Guarda la versión final.'], nota: "Tres o quatre al projector i la resta per grups o en galeria d'estands.|Tres o cuatro en el proyector y el resto por grupos o en galería de estands." },
      { id: 's13', k: 'concepte', t: 'Dissenyadors i dissenyadores 3D|Diseñadores y diseñadoras 3D', x: 'Cada alumne/a rep el diploma del curs Tech 3D · Nivell 1.|Cada alumno/a recibe el diploma del curso Tech 3D · Nivel 1.', nota: "Lliura els diplomes un a un amb un aplaudiment. A l'app, el pas del diploma també es pot imprimir.|Entrega los diplomas uno a uno con un aplauso. En la app, el paso del diploma también se puede imprimir." },
      { id: 's14', k: 'resum', t: 'Avui hem après…|Hoy hemos aprendido…', punts: ['Presentar un disseny en quatre parts.|Presentar un diseño en cuatro partes.', "Descarregar l'STL per imprimir-lo.|Descargar el STL para imprimirlo.", 'Tot el camí del disseny 3D.|Todo el camino del diseño 3D.'], nota: 'Llegiu-ho junts.|Leedlo juntos.' },
      { id: 's15', k: 'tiquet', t: 'Tiquet de sortida|Ticket de salida', punts: ['Tres coses que has après al curs.|Tres cosas que has aprendido en el curso.', 'El teu proper invent.|Tu próximo invento.'], nota: "Escolta les respostes com a avaluació final del curs.|Escucha las respuestas como evaluación final del curso." },
      { id: 's16', k: 'concepte', t: 'A casa|En casa', x: "Ensenya el teu disseny des de «Projectes» i, si podeu, imprimiu-ne l'STL.|Enseña tu diseño desde «Proyectos» y, si podéis, imprimid su STL.", nota: 'Proposta opcional.|Propuesta opcional.' }
    ],
    print: [
      { id: 'p1', t: 'Guió de la presentació i fitxa del producte|Guion de la presentación y ficha del producto', k: 'fitxa', intro: "Escriu unes paraules per a cada part: et recordaran què vols dir. La fitxa anirà al teu estand.|Escribe unas palabras para cada parte: te recordarán qué quieres decir. La ficha irá en tu estand.",
        items: [{ q: 'Nom del disseny: ____ · Per a qui és: ____ · Què fa: ____|Nombre del diseño: ____ · Para quién es: ____ · Qué hace: ____', sol: "Per exemple: Test de l'hort · per als infants de P4 · hi creixen plantes a la finestra.|Por ejemplo: Maceta del huerto · para los niños de P4 · en ella crecen plantas en la ventana." },
          { q: 'Mides: ____ × ____ × ____ mm · Material: ____ · La millor vista: ____|Medidas: ____ × ____ × ____ mm · Material: ____ · La mejor vista: ____', sol: "Les mides de tot el model (Totes → Mida) i la vista que l'ensenya millor.|Las medidas de todo el modelo (Todas → Medida) y la vista que lo enseña mejor." },
          { q: "Com l'he fet (formes i eines): ____|Cómo lo he hecho (formas y herramientas): ____", sol: "Per exemple: un cilindre buidat, forats amb Duplica i nanses amb Mirall.|Por ejemplo: un cilindro vaciado, agujeros con Duplica y asas con Espejo." },
          { q: 'Què he millorat gràcies a la revisió: ____|Qué he mejorado gracias a la revisión: ____', sol: 'Resposta oberta: valoreu que expliqui un desig concret i com el va aplicar.|Respuesta abierta: valorad que explique un deseo concreto y cómo lo aplicó.' },
          { q: 'La pregunta que faré al públic: ____|La pregunta que haré al público: ____', sol: "Per exemple: «Què hi afegiríeu?»|Por ejemplo: «¿Qué le añadiríais?»" }] },
      { id: 'p2', t: 'Diploma del curs|Diploma del curso', k: 'diploma',
        intro: "ha completat el curs Tech 3D · Nivell 1 de Numi Tech: ha dissenyat, modelat, revisat i presentat el seu propi objecte per imprimir en 3D.|ha completado el curso Tech 3D · Nivel 1 de Numi Tech: ha diseñado, modelado, revisado y presentado su propio objeto para imprimir en 3D.",
        items: [
          "Ha après a mirar en 3D i a fer servir les vistes de davant, de dalt i de costat.|Ha aprendido a mirar en 3D y a usar las vistas de delante, de arriba y de lado.",
          'Ha construït amb formes, mesures en mil·límetres, girs i escales.|Ha construido con formas, medidas en milímetros, giros y escalas.',
          'Ha fet servir Alinea, Duplica, Mirall i forats per construir objectes precisos.|Ha usado Alinea, Duplica, Espejo y agujeros para construir objetos precisos.',
          "Ha preparat models per imprimir en 3D i n'ha exportat l'STL.|Ha preparado modelos para imprimir en 3D y ha exportado su STL.",
          'Ha dissenyat per a persones: encàrrec, requisits, revisió i millora.|Ha diseñado para personas: encargo, requisitos, revisión y mejora.'
        ] }
    ]
  }
  };
})());
